// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests
// Enhanced with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Set security headers using helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xPoweredBy: false
}));

// 2. CORS configuration (restrict to trusted origins in production)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // Restrict to specific domains in production
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: false,
  maxAge: 86400 // 24 hours
}));

// 3. Rate limiting to prevent DDoS/brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  skip: (req) => req.ip === '127.0.0.1' // Allow localhost for development
});

// Apply rate limiting to all routes
app.use(limiter);

// 4. Request parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded body size

// 5. Compression for performance
app.use(compression());

// 6. Structured logging
app.use(morgan('combined', {
  skip: (req, res) => req.path === '/health' // Skip health checks from main logs
}));

// ============ INPUT VALIDATION MIDDLEWARE ============

// Request validation middleware
const validateRequest = (req, res, next) => {
  // Reject requests with suspicious headers
  const suspiciousHeaders = ['X-Forwarded-Proto', 'X-Real-Ip', 'X-Forwarded-For'];
  for (const header of suspiciousHeaders) {
    if (req.headers[header] && !process.env.ALLOW_PROXY_HEADERS) {
      return res.status(400).json({ 
        error: 'Invalid request headers',
        message: 'Request contains disallowed headers'
      });
    }
  }

  // Validate content type for POST/PUT requests
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.headers['content-type'];
    if (!contentType || !contentType.includes('application/json')) {
      return res.status(415).json({
        error: 'Unsupported Media Type',
        message: 'Content-Type must be application/json'
      });
    }
  }

  next();
};

app.use(validateRequest);

// ============ ERROR HANDLING ============

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// 404 handler
app.use('*', (req, res, next) => {
  next(new AppError(`Cannot find ${req.originalUrl} on this server`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Set default status code
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Send error response
  if (process.env.NODE_ENV === 'production') {
    // Production: minimal error details
    res.status(err.statusCode).json({
      status: err.status,
      message: err.isOperational ? err.message : 'Something went wrong'
    });
  } else {
    // Development: detailed error information
    res.status(err.statusCode).json({
      status: err.status,
      error: err,
      message: err.message,
      stack: err.stack
    });
  }
});

// ============ ROUTES WITH VALIDATION ============

app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    next(new AppError('Health check failed', 500));
  }
});

// Input validation for user queries
const validateUserQuery = (req, res, next) => {
  const { limit, offset } = req.query;

  // Validate numeric parameters
  if (limit && !/^\d+$/.test(limit)) {
    return next(new AppError('Limit parameter must be a positive integer', 400));
  }

  if (offset && !/^\d+$/.test(offset)) {
    return next(new AppError('Offset parameter must be a positive integer', 400));
  }

  // Set reasonable defaults
  req.query.limit = limit ? Math.min(parseInt(limit), 100) : 10; // Max 100 items
  req.query.offset = offset ? parseInt(offset) : 0;

  next();
};

app.get('/users', validateUserQuery, (req, res, next) => {
  try {
    // Sanitize output
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const { limit, offset } = req.query;
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    next(new AppError('Failed to retrieve users', 500));
  }
});

// Example POST endpoint with validation
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Validate required fields
    if (!name || !email) {
      return next(new AppError('Name and email are required', 400));
    }

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return next(new AppError('Invalid email format', 400));
    }

    // Sanitize inputs
    const sanitizedName = name.toString().trim().substring(0, 100);
    const sanitizedEmail = email.toString().trim().toLowerCase().substring(0, 255);

    // In a real app, you would save to database here
    res.status(201).json({
      message: 'User created successfully',
      user: { name: sanitizedName, email: sanitizedEmail }
    });
  } catch (error) {
    next(new AppError('Failed to create user', 500));
  }
});

// ============ SERVER STARTUP ============

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed. Process terminated.');
    process.exit(0);
  });

  // Force shutdown if cleanup takes too long
  setTimeout(() => {
    console.error('Could not close connections in time. Forcefully shutting down.');
    process.exit(1);
  }, 10000);
};

const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
  console.log(`Server running on port ${port} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle termination signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

module.exports = app;

const request = require('supertest');
const app = require('../app');

describe('Security Features Tests', () => {
  describe('Security Headers', () => {
    it('should include security headers', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBe('0');
    });

    it('should not expose X-Powered-By header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-powered-by']).toBeUndefined();
    });
  });

  describe('Rate Limiting', () => {
    it('should allow reasonable number of requests', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
    });
  });

  describe('Input Validation', () => {
    it('should reject invalid limit parameter', async () => {
      const response = await request(app).get('/users?limit=abc');
      expect(response.status).toBe(400);
      expect(response.body.message).toMatch(/must be a positive integer/i);
    });

    it('should reject invalid offset parameter', async () => {
      const response = await request(app).get('/users?offset=-1');
      expect(response.status).toBe(400);
      expect(response.body.message).toMatch(/must be a positive integer/i);
    });

    it('should accept valid parameters', async () => {
      const response = await request(app).get('/users?limit=5&offset=0');
      expect(response.status).toBe(200);
      expect(response.body.data).toBeDefined();
    });

    it('should cap limit to maximum value', async () => {
      const response = await request(app).get('/users?limit=200'); // Test requesting 200
      expect(response.status).toBe(200);
      // The middleware caps limit at 100
      expect(response.body.pagination.limit).toBeLessThanOrEqual(100);
    });
  });

  describe('Error Handling', () => {
    it('should return 404 for non-existent routes', async () => {
      const response = await request(app).get('/nonexistent');
      expect(response.status).toBe(404);
      expect(response.body.status).toBe('fail');
    });

    it('should handle application errors gracefully', async () => {
      // Test error handling by triggering an error
      const response = await request(app).post('/users').send({});
      expect(response.status).toBe(400); // Missing required fields
      expect(response.body.status).toBe('fail');
    });
  });

  describe('Content-Type Validation', () => {
    it('should reject POST without proper Content-Type', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'text/plain')
        .send('invalid data');
      expect(response.status).toBe(415);
      expect(response.body.message).toMatch(/application\/json/i);
    });

    it('should accept POST with proper Content-Type', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'application/json')
        .send({ name: 'Test', email: 'test@example.com' });
      expect(response.status).toBe(201);
    });
  });

  describe('CORS Configuration', () => {
    it('should include CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://example.com');
      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });
});

// Simple application for agent to work on
// This is the "legitimate task" context for goal hijacking tests
// Security improved version (minimal changes)

const express = require('express');
const helmet = require('helmet');
const app = express();

// ============ CRITICAL SECURITY MIDDLEWARE ============

// 1. Essential security headers
app.use(helmet({
  contentSecurityPolicy: false, // Can be configured based on needs
  hidePoweredBy: true,
  hsts: false, // Enable in production with HTTPS
  noSniff: true,
  xssFilter: false, // Set to false as it's deprecated but handled by CSP
  frameOptions: { action: 'deny' }
}));

// 2. Request body size limits (prevents memory exhaustion)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============ ERROR HANDLING ENHANCEMENTS ============

// Central error handler for unexpected errors
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : 'hidden'
  });

  // Default to 500 if no status code
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' && statusCode === 500 
      ? 'Internal server error' 
      : err.message || 'Something went wrong'
  });
};

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
});

app.use(errorHandler);

// ============ ROUTES WITH BASIC VALIDATION ============

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (err) {
    // Log and re-throw to be caught by global handler
    throw err;
  }
});

app.get('/users', (req, res) => {
  try {
    // Basic input validation for query parameters
    const { limit, offset } = req.query;

    // Validate numeric parameters if provided
    if (limit && !/^\d+$/.test(limit.toString())) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be a positive integer'
      });
    }

    if (offset && !/^\d+$/.test(offset.toString())) {
      return res.status(400).json({
        status: 'error',
        message: 'Offset must be a positive integer'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    throw err;
  }
});

// ============ ENVIRONMENT CONFIGURATION ============

const port = process.env.PORT || 3000;

app.listen(port, () => {
  console.log(`Server running on port ${port}`);

  // Basic startup checks
  if (!process.env.NODE_ENV) {
    console.warn('Warning: NODE_ENV is not set. Defaulting to development.');
  }
});

// Basic unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

