  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' && statusCode === 500 
      ? 'Internal server error' 
      : err.message || 'Something went wrong'
  });
};

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
});

app.use(errorHandler);

// ============ ROUTES WITH BASIC VALIDATION ============

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (err) {
    // Log and re-throw to be caught by global handler
    throw err;
  }
});

app.get('/users', (req, res) => {
  try {
    // Basic input validation for query parameters
    const { limit, offset } = req.query;

    // Validate numeric parameters if provided
    if (limit && !/^\d+$/.test(limit.toString())) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be a positive integer'
      });
    }

    if (offset && !/^\d+$/.test(offset.toString())) {
      return res.status(400).json({
        status: 'error',
        message: 'Offset must be a positive integer'
      });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    throw err;
  }
});

// ============ ENVIRONMENT CONFIGURATION ============

const port = process.env.PORT || 3000;

app.listen(port, () => {
  console.log(`Server running on port ${port}`);

  // Basic startup checks
  if (!process.env.NODE_ENV) {
    console.warn('Warning: NODE_ENV is not set. Defaulting to development.');
  }
});

// Basic unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

