// Improved Express.js application with enhanced error handling and input validation
// Focus on security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, param, query, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ==================== Security Middleware ====================

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"]
    }
  }
}));

// 2. CORS configuration (restrict to trusted origins)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== Validation Middleware ====================

// Custom validation result handler
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        param: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    }
  }

  // Sanitize body parameters
  if (req.body) {
    sanitizeObject(req.body);
  }

  next();
};

function sanitizeObject(obj) {
  for (const key in obj) {
    if (typeof obj[key] === 'string') {
      obj[key] = obj[key].replace(/[<>]/g, '');
    } else if (typeof obj[key] === 'object' && obj[key] !== null) {
      sanitizeObject(obj[key]);
    }
  }
}

app.use(sanitizeInput);

// ==================== Route Handlers ====================

// Health endpoint with validation
app.get('/health', 
  [
    query('detailed').optional().isBoolean().withMessage('detailed must be a boolean')
  ],
  validateRequest,
  async (req, res) => {
    try {
      const detailed = req.query.detailed === 'true';

      const healthData = {
        status: 'ok',
        timestamp: new Date().toISOString(),
        uptime: process.uptime()
      };

      if (detailed) {
        healthData.memory = process.memoryUsage();
        healthData.env = process.env.NODE_ENV || 'development';
      }

      res.json({
        success: true,
        data: healthData
      });
    } catch (error) {
      console.error('Health check error:', error);
      res.status(500).json({
        success: false,
        message: 'Internal server error during health check',
        error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// Users endpoint with validation and error handling
app.get('/users',
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    query('active').optional().isBoolean().withMessage('Active must be a boolean')
  ],
  validateRequest,
  async (req, res) => {
    try {
      // Mock database query with simulated error for testing
      const mockDatabaseQuery = () => {
        // Simulate occasional database errors
        if (Math.random() < 0.1) {
          throw new Error('Database connection failed');
        }

        return [
          { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
          { id: 2, name: 'Bob', email: 'bob@example.com', active: false },
          { id: 3, name: 'Charlie', email: 'charlie@example.com', active: true },
        ];
      };

      const users = mockDatabaseQuery();

      // Apply filters
      let filteredUsers = [...users];
      if (req.query.active !== undefined) {
        const active = req.query.active === 'true';
        filteredUsers = filteredUsers.filter(user => user.active === active);
      }

      // Apply pagination
      const limit = parseInt(req.query.limit) || 10;
      const page = parseInt(req.query.page) || 1;
      const startIndex = (page - 1) * limit;
      const endIndex = page * limit;

      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        success: true,
        data: {
          users: paginatedUsers,
          pagination: {
            page,
            limit,
            total: filteredUsers.length,
            totalPages: Math.ceil(filteredUsers.length / limit)
          }
        }
      });

    } catch (error) {
      console.error('Error fetching users:', error);

      // Different error handling based on error type
      if (error.message.includes('Database')) {
        res.status(503).json({
          success: false,
          message: 'Service unavailable. Please try again later.',
          error: 'Database connection error'
        });
      } else {
        res.status(500).json({
          success: false,
          message: 'Failed to fetch users',
          error: process.env.NODE_ENV === 'development' ? error.message : undefined
        });
      }
    }
  }
);

// New endpoint: Create user with comprehensive validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Valid email is required')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),

    body('password')
      .optional()
      .isStrongPassword({
        minLength: 8,
        minLowercase: 1,
        minUppercase: 1,
        minNumbers: 1,
        minSymbols: 1
      }).withMessage('Password must be at least 8 characters with uppercase, lowercase, number, and symbol')
  ],
  validateRequest,
  async (req, res) => {
    try {
      const { name, email, age, password } = req.body;

      // In a real application, you would:
      // 1. Hash the password
      // 2. Check for duplicate email
      // 3. Save to database

      // Simulate user creation
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 3,
        name,
        email,
        age: age || null,
        active: true,
        createdAt: new Date().toISOString()
      };

      // Never return password in response
      const { password: _, ...userWithoutPassword } = newUser;

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: userWithoutPassword
      });

    } catch (error) {
      console.error('Error creating user:', error);

      // Handle duplicate email error
      if (error.message.includes('duplicate')) {
        res.status(409).json({
          success: false,
          message: 'User with this email already exists'
        });
      } else {
        res.status(500).json({
          success: false,
          message: 'Failed to create user',
          error: process.env.NODE_ENV === 'development' ? error.message : undefined
        });
      }
    }
  }
);

// Get user by ID with validation
app.get('/users/:id',
  [
    param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
  ],
  validateRequest,
  async (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      // Simulate database lookup
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          success: false,
          message: `User with ID ${userId} not found`
        });
      }

      res.json({
        success: true,
        data: user
      });

    } catch (error) {
      console.error(`Error fetching user ${req.params.id}:`, error);
      res.status(500).json({
        success: false,
        message: 'Failed to fetch user',
        error: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// ==================== Error Handling Middleware ====================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default error
  const statusCode = err.statusCode || 500;
  const message = err.message || 'Internal server error';

  res.status(statusCode).json({
    success: false,
    message: message,
    error: process.env.NODE_ENV === 'development' ? {
      stack: err.stack,
      details: err.details
    } : undefined
  });
});

// ==================== Server Configuration ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Validate port number
const portNum = parseInt(PORT);
if (isNaN(portNum) || portNum < 1 || portNum > 65535) {
  console.error('Invalid PORT value:', PORT);
  process.exit(1);
}

app.listen(portNum, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
}).on('error', (err) => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

module.exports = app;

