// Enhanced Express application with comprehensive security and error handling
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
require('dotenv').config(); // Load environment variables from .env file

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet for security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'", "data:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year in seconds
        includeSubDomains: true,
        preload: true
    },
    referrerPolicy: { policy: 'same-origin' }
}));

// 2. CORS configuration
const corsOptions = {
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    standardHeaders: true,
    legacyHeaders: false,
    message: {
        error: 'Too many requests from this IP, please try again later.',
        retryAfter: 900 // 15 minutes in seconds
    }
});
app.use(limiter);

// 4. Request logging
app.use(morgan('combined', {
    skip: (req, res) => process.env.NODE_ENV === 'test' || req.path === '/health'
}));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========== ERROR HANDLING MIDDLEWARE ==========

// Global error handler
const errorHandler = (err, req, res, next) => {
    console.error(`[${new Date().toISOString()}] Error:`, {
        message: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
        path: req.path,
        method: req.method,
        ip: req.ip
    });

    // Don't leak error details in production
    const errorResponse = {
        error: process.env.NODE_ENV === 'production' 
            ? 'An unexpected error occurred' 
            : err.message,
        status: 'error'
    };

    // Handle specific error types
    if (err.name === 'ValidationError') {
        return res.status(400).json({
            ...errorResponse,
            error: 'Validation failed',
            details: err.errors
        });
    }

    if (err.name === 'UnauthorizedError') {
        return res.status(401).json({
            ...errorResponse,
            error: 'Authentication required'
        });
    }

    // Default error
    res.status(err.status || 500).json(errorResponse);
};

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: process.env.NODE_ENV || 'development'
    });
});

// Users endpoint with validation (example with query parameters)
app.get('/users', 
    // Input validation for query parameters
    [
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
    ],
    (req, res, next) => {
        try {
            // Validate input
            const errors = validationResult(req);
            if (!errors.isEmpty()) {
                return res.status(400).json({ 
                    error: 'Validation failed', 
                    details: errors.array() 
                });
            }

            // Example: Validate environment variables are loaded
            if (!process.env.NODE_ENV) {
                throw new Error('Environment configuration error');
            }

            // Process query parameters safely
            const limit = parseInt(req.query.limit) || 10;
            const offset = parseInt(req.query.offset) || 0;

            // Example data (in real app, this would come from a validated source)
            const users = [
                { 
                    id: 1, 
                    name: 'Alice', 
                    email: 'alice@example.com',
                    created: new Date().toISOString()
                },
                { 
                    id: 2, 
                    name: 'Bob', 
                    email: 'bob@example.com',
                    created: new Date().toISOString()
                },
            ];

            // Apply pagination safely
            const paginatedUsers = users.slice(offset, offset + limit);

            res.json({
                data: paginatedUsers,
                pagination: {
                    total: users.length,
                    limit,
                    offset,
                    hasMore: offset + limit < users.length
                },
                meta: {
                    timestamp: new Date().toISOString(),
