// Improved Express Application with comprehensive error handling and security best practices
// This version includes proper input validation, security headers, rate limiting, and error handling

const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const expressWinston = require('express-winston'); // Request logging
const winston = require('winston'); // Logging
const Joi = require('joi'); // Input validation
const { sanitize } = require('express-sanitizer'); // Input sanitization

const app = express();
const PORT = process.env.PORT || 3000;

// ========== SECURITY MIDDLEWARE ==========

// 1. Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'same-origin' }
}));

// 2. CORS configuration (restrict to trusted domains in production)
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000']
    : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 900 // 15 minutes in seconds
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 4. Request size limits
app.use(express.json({ limit: '10kb' })); // JSON body size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body size limit

// 5. Input sanitization to prevent XSS attacks
app.use(sanitize());

// ========== LOGGING MIDDLEWARE ==========

// Request logging
app.use(expressWinston.logger({
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'logs/requests.log' })
  ],
  format: winston.format.combine(
    winston.format.colorize(),
    winston.format.json()
  ),
  meta: true,
  msg: 'HTTP {{req.method}} {{req.url}}',
  expressFormat: true,
  colorize: false,
  ignoreRoute: function (req, res) { return false; }
}));

// ========== INPUT VALIDATION MIDDLEWARE ==========

// Validation schemas
const queryValidationSchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  search: Joi.string().max(100).optional()
});

const userIdValidationSchema = Joi.object({
  id: Joi.string().pattern(/^[0-9]+$/).required()
});

// Validation middleware
const validateQuery = (req, res, next) => {
  const { error, value } = queryValidationSchema.validate(req.query);
  if (error) {
    return res.status(400).json({
      error: 'Validation Error',
      details: error.details.map(detail => detail.message)
    });
  }
  req.validatedQuery = value;
  next();
};

const validateUserId = (req, res, next) => {
  const { error, value } = userIdValidationSchema.validate(req.params);
  if (error) {
    return res.status(400).json({
      error: 'Validation Error',
      details: error.details.map(detail => detail.message)
    });
  }
  req.validatedParams = value;
  next();
};

// ========== ROUTES WITH IMPROVED ERROR HANDLING ==========

// Health check endpoint with error simulation
app.get('/health', (req, res, next) => {
  try {
    // Simulate database health check
    const dbIsHealthy = true; // In real app, check actual database connection

    if (!dbIsHealthy) {
      throw new Error('Database connection failed');
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Users endpoint with query parameter validation
app.get('/users', validateQuery, (req, res, next) => {
  try {
    const { page, limit, search } = req.validatedQuery;
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // Simulate database query with filtering
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Pagination calculation
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// User detail endpoint with parameter validation
app.get('/users/:id', validateUserId, (req, res, next) => {
  try {
    const { id } = req.validatedParams;
    const userId = parseInt(id, 10);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      const error = new Error('User not found');
      error.statusCode = 404;
      throw error;
    }

    // Sanitize user data before returning (example: remove sensitive fields)
    const sanitizedUser = {
      id: user.id,
      name: user.name,
      email: user.email,
      // role: user.role // Don't expose role in public API
    };

    res.json({
      data: sanitizedUser
    });
  } catch (error) {
    next(error); // Pass to error handling middleware
  }
});

// Example POST endpoint with body validation
app.post('/users', (req, res, next) => {
  try {
    // Validate request body
    const userSchema = Joi.object({
      name: Joi.string().min(2).max(50).required(),
      email: Joi.string().email().required(),
      password: Joi.string().min(8).max(100).required(),
      role: Joi.string().valid('user', 'admin').default('user')
    });

    const { error, value } = userSchema.validate(req.body);
    if (error) {
      const validationError = new Error('Validation failed');
      validationError.statusCode = 400;
      validationError.details = error.details;
      throw validationError;
    }

    // Process valid data (in a real app, this would be saved to database)
    const newUser = {
      id: Date.now(), // Temporary ID generation
      ...value
    };

    // Never store plain text passwords or include them in responses
    delete newUser.password;

    res.status(201).json({
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    timestamp: new Date().toISOString()
  });
});

// Error logging
app.use(expressWinston.errorLogger({
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'logs/errors.log' })
  ],
  format: winston.format.combine(
    winston.format.colorize(),
    winston.format.json()
  )
}));

// Global error handler
app.use((error, req, res, next) => {
  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal Server Error';

  // Don't expose stack traces in production
  const response = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred. Please try again later.'
      : message,
    timestamp: new Date().toISOString()
  };

  // Include validation details if available
  if (error.details && process.env.NODE_ENV !== 'production') {
    response.details = error.details;
  }

  // Log detailed error for debugging
  console.error(`[${new Date().toISOString()}] Error:`, {
    message: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  res.status(statusCode).json(response);
});

// ========== SERVER STARTUP ==========

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Start server with error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Server started at: ${new Date().toISOString()}`);
}).on('error', (error) => {
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Failed to start server:', error.message);
  }
  process.exit(1);
});

// Graceful shutdown
const gracefulShutdown = () => {
  console.log('Received shutdown signal, shutting down gracefully...');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = { app, server };

// Express Application with Essential Security and Error Handling Improvements
// Minimal changes to original app.js with critical security enhancements

const express = require('express');
const app = express();
const PORT = process.env.PORT || 3000;

// ========== ESSENTIAL SECURITY IMPROVEMENTS ==========

// 1. Basic security headers (without external dependencies)
app.use((req, res, next) => {
  // Set security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Referrer-Policy', 'same-origin');
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');
  next();
});

// 2. Input validation helper function
const validateParameters = (params) => {
  const errors = [];

  // Validate numeric parameters
  if (params.id) {
    const id = parseInt(params.id, 10);
    if (isNaN(id) || id <= 0) {
      errors.push('id must be a positive number');
    }
  }

  // Validate query parameters
  if (params.page) {
    const page = parseInt(params.page, 10);
    if (isNaN(page) || page < 1) {
      errors.push('page must be a positive number');
    }
  }

  if (params.limit) {
    const limit = parseInt(params.limit, 10);
    if (isNaN(limit) || limit < 1 || limit > 100) {
      errors.push('limit must be between 1 and 100');
    }
  }

  // Validate string parameters for injection attempts
  if (params.search) {
    const search = params.search.toString();
    if (search.length > 100) {
      errors.push('search must be less than 100 characters');
    }
    // Simple SQL injection prevention
    const sqlInjectionPatterns = [';', '--', 'DROP ', 'DELETE ', 'UPDATE ', 'INSERT ', 'SELECT ', 'UNION '];
    const upperSearch = search.toUpperCase();
    if (sqlInjectionPatterns.some(pattern => upperSearch.includes(pattern))) {
      errors.push('search contains invalid characters');
    }
  }

  return errors;
};

// 3. Error handling middleware
app.use((req, res, next) => {
  // Centralized error handler
  res.errorResponse = function(statusCode, message, details = null) {
    const response = {
      error: message,
      timestamp: new Date().toISOString()
    };

    if (details && process.env.NODE_ENV !== 'production') {
      response.details = details;
    }

    return this.status(statusCode).json(response);
  };
  next();
});

// ========== ROUTES WITH IMPROVED ERROR HANDLING ==========

app.get('/health', (req, res) => {
  try {
    const healthCheck = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Add environment info (sanitized)
    if (process.env.NODE_ENV) {
      healthCheck.environment = process.env.NODE_ENV;
    }

    res.json(healthCheck);
  } catch (error) {
    console.error('Health check error:', error);
    res.errorResponse(500, 'Internal server error');
  }
});

app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const errors = validateParameters(req.query);
    if (errors.length > 0) {
      return res.errorResponse(400, 'Validation error', errors);
    }

    const { page = 1, limit = 10, search } = req.query;
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter (case-insensitive)
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = startIndex + limitNum;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    // Sanitize data - ensure no sensitive information is exposed
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: escapeHtml(user.name), // Basic XSS protection
      email: user.email // Email is safe as it's already validated
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limitNum)
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.errorResponse(500, 'Internal server error');
  }
});

// ========== HELPER FUNCTIONS ==========

// Basic HTML escaping to prevent XSS
function escapeHtml(text) {
  if (!text) return '';
  return text.toString()
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ========== GLOBAL ERROR HANDLING ==========

// 404 handler
app.use((req, res) => {
  res.errorResponse(404, 'Not found', `Cannot ${req.method} ${req.url}`);
});

// Global error handler for unhandled errors
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't expose error details in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : error.message || 'Internal server error';

  res.errorResponse(500, message);
});

// ========== SERVER STARTUP ==========

const server = app.listen(PORT, () => {
  console.log('Server running on port', PORT);

  // Log startup with environment info
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Startup time: ${new Date().toISOString()}`);
}).on('error', (error) => {
  console.error('Failed to start server:', error.message);
  if (error.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  }
  process.exit(1);
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
