      errors.push('Input too long (max 1000 characters)');
    }
  }

  // Validate numeric inputs
  if (input && typeof input === 'string' && !isNaN(input)) {
    const num = parseInt(input, 10);
    if (num < 0) {
      errors.push('Negative numbers not allowed');
    }
  }

  return errors;
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Centralized error response helper
const errorResponse = (res, statusCode, message, details = null) => {
  const response = {
    error: message,
    timestamp: new Date().toISOString()
  };

  // Only include details in development (not production)
