// Enhanced application with comprehensive error handling and input validation
// Security-focused improvements for production readiness

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const joi = require('joi'); // Input validation library
const { validationErrorHandler, errorHandler, notFoundHandler } = require('./middleware/errorHandlers');

const app = express();

// ============= SECURITY MIDDLEWARE =============

// 1. Set security headers using Helmet
app.use(helmet());

// 2. Configure CORS for production (restrict origins)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));
app.options('*', cors(corsOptions)); // Pre-flight requests

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  skip: (req) => req.ip === '127.0.0.1' || req.ip === '::1' // Allow localhost for testing
});
app.use('/api/', limiter);

// 4. Request logging (use 'combined' for production)
app.use(morgan('dev'));

// 5. Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent DoS with large payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============= INPUT VALIDATION SCHEMAS =============

const userQuerySchema = joi.object({
  page: joi.number().integer().min(1).default(1),
  limit: joi.number().integer().min(1).max(100).default(10),
  sort: joi.string().valid('id', 'name', 'email').default('id'),
  direction: joi.string().valid('asc', 'desc').default('asc')
});

const userCreateSchema = joi.object({
  name: joi.string().trim().min(1).max(100).required(),
  email: joi.string().trim().email().max(255).required(),
  role: joi.string().valid('user', 'admin').default('user')
});

// ============= VALIDATION MIDDLEWARE =============

const validateRequest = (schema, property = 'body') => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[property], {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      const validationErrors = error.details.map(detail => ({
        field: detail.path.join('.'),
        message: detail.message.replace(/"/g, '')
      }));

      return res.status(400).json({
        success: false,
        error: 'Validation failed',
        details: validationErrors,
        timestamp: new Date().toISOString()
      });
    }

    // Replace request data with validated and sanitized data
    req[property] = value;
    next();
  };
};

// ============= ENHANCED HEALTH ENDPOINT =============

app.get('/health', (req, res) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      nodeVersion: process.version,
      env: process.env.NODE_ENV || 'development'
    };

    res.set('Cache-Control', 'no-store'); // Prevent caching of health checks
    res.json(healthStatus);
  } catch (error) {
    console.error('Health check failed:', error);
    res.status(503).json({
      status: 'error',
      message: 'Service temporarily unavailable',
      timestamp: new Date().toISOString()
    });
  }
});

// ============= ENHANCED USERS ENDPOINTS =============

// GET /users with query validation
app.get('/users', validateRequest(userQuerySchema, 'query'), async (req, res, next) => {
  try {
    const { page, limit, sort, direction } = req.query;

    // Simulated database query with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Implement pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = users.slice(startIndex, endIndex);

    // Implement sorting
    paginatedUsers.sort((a, b) => {
      const aValue = a[sort];
      const bValue = b[sort];
      if (direction === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue > bValue ? -1 : 1;
      }
    });

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error); // Pass to centralized error handler
  }
});

// POST /users with input validation
app.post('/users', validateRequest(userCreateSchema), async (req, res, next) => {
  try {
    const { name, email, role } = req.body;

    // Additional business logic validation
    if (email.includes('admin') && role !== 'admin') {
      return res.status(400).json({
        success: false,
        error: 'Admin email requires admin role'
      });
    }

    // Simulate user creation
    const newUser = {
      id: Math.floor(Math.random() * 1000) + 100,
      name: name.trim(),
      email: email.toLowerCase().trim(),
      role,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// ============= ERROR HANDLING =============

// 404 handler for undefined routes
app.use(notFoundHandler);

// Joi validation error handler
app.use(validationErrorHandler);

// Centralized error handler
app.use(errorHandler);

// ============= UNCAUGHT EXCEPTION HANDLING =============

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

