const validateQueryParams = (req, res, next) => {
  // Basic validation for query parameters
  if (req.query.page && isNaN(parseInt(req.query.page))) {
    return res.status(400).json({ 
      error: 'Validation Error', 
      message: 'page parameter must be a number' 
    });
  }

  if (req.query.limit && (isNaN(parseInt(req.query.limit)) || parseInt(req.query.limit) > 100)) {
    return res.status(400).json({ 
      error: 'Validation Error', 
      message: 'limit parameter must be a number between 1 and 100' 
    });
  }

  next();
};

// Basic sanitization for user input
const sanitizeUserInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
      }
    });
  }

  // Sanitize body parameters (if body parser is added)
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
      }
    });
