// Enhanced Express application with comprehensive error handling and security best practices
const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const mongoSanitize = require('express-mongo-sanitize'); // MongoDB injection protection
const xss = require('xss-clean'); // XSS protection
const hpp = require('hpp'); // Parameter pollution protection
const compression = require('compression'); // Gzip compression
const { body, validationResult } = require('express-validator'); // Input validation

const app = express();

// Load environment variables securely
require('dotenv').config();

// Security Middleware ====================================================

// 1. Set security HTTP headers
app.use(helmet());

// 2. Enable CORS with secure configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? process.env.ALLOWED_ORIGINS?.split(',') || []
    : '*',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again later.' 
  },
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skipSuccessfulRequests: false,
  keyGenerator: (req) => req.ip // Use IP address as the key
});
app.use('/api', limiter);

// 4. Body parsing (limit payload size to prevent DoS)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Data sanitization against NoSQL injection
app.use(mongoSanitize());

// 6. Data sanitization against XSS
app.use(xss());

// 7. Prevent parameter pollution
app.use(hpp());

// 8. Compression for performance
app.use(compression());

// Custom Middleware ======================================================

// Request logging middleware
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent')
    });
  });
  next();
});

// Error logging middleware
const errorLogger = (err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });
  next(err);
};

// Routes with Input Validation ==========================================

// Enhanced health endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memory: process.memoryUsage(),
    nodeVersion: process.version
  });
});

// Users endpoint with validation and sanitization
app.get('/users', 
  // Input validation middleware
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('search').optional().trim().escape().isLength({ max: 100 }).withMessage('Search term too long')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array() 
      });
    }

    try {
      // Simulate database query with sanitized inputs
      const { limit = 10, page = 1, search } = req.query;

      // Input sanitization for SQL-like parameters
      const safeLimit = Math.min(Math.max(parseInt(limit), 1), 100);
      const safePage = Math.max(parseInt(page), 1);

      // Mock user data (in real app, this would come from database)
      const users = [
        { 
          id: 1, 
          name: 'Alice', 
          email: 'alice@example.com',
          role: 'user',
          createdAt: '2024-01-01'
        },
        { 
          id: 2, 
          name: 'Bob', 
          email: 'bob@example.com',
          role: 'admin',
          createdAt: '2024-01-02'
        }
      ];

      // Apply search filter if provided
      const filteredUsers = search 
        ? users.filter(user => 
            user.name.toLowerCase().includes(search.toLowerCase()) ||
            user.email.toLowerCase().includes(search.toLowerCase())
          )
        : users;

      // Calculate pagination
      const startIndex = (safePage - 1) * safeLimit;
      const endIndex = startIndex + safeLimit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          total: filteredUsers.length,
          page: safePage,
          limit: safeLimit,
          pages: Math.ceil(filteredUsers.length / safeLimit)
        }
      });
    } catch (error) {
      // Log and handle unexpected errors
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

