// Improved Express.js application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();

// ========================
// 1. SECURITY MIDDLEWARE
// ========================

// a) HTTP Security Headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year in seconds
        includeSubDomains: true,
        preload: true
    }
}));

// b) CORS Configuration (Restrict to trusted origins)
const corsOptions = {
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// c) Rate Limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});
app.use('/api/', limiter); // Apply to all /api routes

// d) Request Size Limits
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ========================
// 2. LOGGING CONFIGURATION
// ========================

// Configure Winston logger
const logger = winston.createLogger({
    level: process.env.LOG_LEVEL || 'info',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    defaultMeta: { service: 'user-service' },
    transports: [
        new winston.transports.Console({
            format: winston.format.simple(),
        }),
        new winston.transports.File({ 
            filename: 'error.log', 
            level: 'error' 
        }),
        new winston.transports.File({ 
            filename: 'combined.log' 
        }),
    ],
});

// ========================
// 3. VALIDATION MIDDLEWARE
// ========================

// Validation error handling middleware
const handleValidationErrors = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            status: 'error',
            errors: errors.array().map(err => ({
                param: err.param,
                msg: err.msg,
                value: err.value
            }))
        });
    }
    next();
};

// Request logging middleware
app.use((req, res, next) => {
    const startTime = Date.now();

    // Log request details (excluding sensitive data)
    logger.info({
        method: req.method,
        url: req.originalUrl,
        ip: req.ip,
        userAgent: req.get('User-Agent'),
        timestamp: new Date().toISOString()
    });

    res.on('finish', () => {
        const duration = Date.now() - startTime;
        logger.info({
            method: req.method,
            url: req.originalUrl,
            statusCode: res.statusCode,
            duration: `${duration}ms`,
            timestamp: new Date().toISOString()
        });
    });

    next();
});

// ========================
// 4. ROUTE HANDLERS WITH VALIDATION
// ========================

// Health check endpoint
app.get('/health', [
    // Optional: Add query parameter validation if needed
], (req, res, next) => {
    try {
        // Simulate database or service health check
        const dbHealth = true; // Replace with actual health check
        const serviceHealth = true; // Replace with actual health check

        if (!dbHealth || !serviceHealth) {
            throw new Error('Service health check failed');
        }

        res.json({
            status: 'healthy',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            checks: {
                database: dbHealth,
                service: serviceHealth
            }
        });
    } catch (error) {
        next(error); // Pass to error handler
    }
});

// Users endpoint with pagination and validation
app.get('/users', [
    // Query parameter validation
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    handleValidationErrors
], async (req, res, next) => {
    try {
        const { page = 1, limit = 10 } = req.query;
        const offset = (page - 1) * limit;

        // In a real application, this would come from a database
        // For demonstration, we'll use mock data
        const mockUsers = [
            { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
            { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
        ];

        // Apply pagination (in real app, this would be a database query)
        const paginatedUsers = mockUsers.slice(offset, offset + parseInt(limit));

        // Sanitize sensitive data before sending response
        const sanitizedUsers = paginatedUsers.map(user => ({
            id: user.id,
            name: user.name,
            role: user.role
            // Note: Email is omitted for privacy
        }));

        res.json({
            status: 'success',
            data: sanitizedUsers,
            pagination: {
                page: parseInt(page),
                limit: parseInt(limit),
                total: mockUsers.length,
                totalPages: Math.ceil(mockUsers.length / limit)
            },
            metadata: {
                requestedAt: new Date().toISOString()
            }
        });
    } catch (error) {
        next(error);
    }
});

// New endpoint: Create user with validation
app.post('/users', [
    // Input validation and sanitization
    body('name')
        .trim()
        .notEmpty().withMessage('Name is required')
        .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
        .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces')
        .escape(),

    body('email')
        .trim()
        .notEmpty().withMessage('Email is required')
        .isEmail().withMessage('Invalid email format')
        .normalizeEmail(),

    body('role')
        .optional()
        .isIn(['user', 'admin', 'moderator']).withMessage('Invalid role specified'),

    handleValidationErrors
], async (req, res, next) => {
    try {
        const { name, email, role = 'user' } = req.body;

        // In a real application:
        // 1. Check if email already exists
        // 2. Hash password if applicable
        // 3. Save to database

        const newUser = {
            id: Date.now(), // Temporary ID
            name,
            email,
            role,
            createdAt: new Date().toISOString()
        };

        logger.info(`New user created: ${email}`);

        res.status(201).json({
            status: 'success',
            message: 'User created successfully',
            data: {
                id: newUser.id,
                name: newUser.name,
                role: newUser.role
                // Email omitted for privacy in response
            }
        });
    } catch (error) {
        next(error);
    }
});

// ========================
// 5. ERROR HANDLING MIDDLEWARE
// ========================

// 404 Not Found handler
app.use((req, res, next) => {
    res.status(404).json({
        status: 'error',
        message: `Route ${req.originalUrl} not found`,
        timestamp: new Date().toISOString()
    });
});

// Global error handler
app.use((error, req, res, next) => {
    const statusCode = error.statusCode || 500;
    const message = error.message || 'Internal Server Error';

    // Log the error
    logger.error({
        error: message,
        stack: error.stack,
        url: req.originalUrl,
        method: req.method,
        ip: req.ip,
        timestamp: new Date().toISOString()
    });

    // Determine error response based on environment
    const errorResponse = {
        status: 'error',
        message: message,
        timestamp: new Date().toISOString()
    };

    // Only include stack trace in development
    if (process.env.NODE_ENV === 'development') {
        errorResponse.stack = error.stack;
    }

    res.status(statusCode).json(errorResponse);
});

// ========================
// 6. GRACEFUL SHUTDOWN
// ========================

const startServer = () => {
    const PORT = process.env.PORT || 3000;
    const server = app.listen(PORT, () => {
        logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
    });

    // Graceful shutdown handlers
    const gracefulShutdown = (signal) => {
        logger.info(`${signal} received, starting graceful shutdown`);

        server.close(() => {
            logger.info('Server closed successfully');
            process.exit(0);
        });

        // Force shutdown after 10 seconds
        setTimeout(() => {
            logger.error('Could not close connections in time, forcefully shutting down');
            process.exit(1);
        }, 10000);
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    return server;
};

// ========================
// 7. ENVIRONMENT CONFIGURATION
// ========================

// Load environment variables
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0 && process.env.NODE_ENV !== 'test') {
    logger.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
    process.exit(1);
}

// Start server if this file is run directly
if (require.main === module) {
    startServer();
}

module.exports = { app, startServer, logger };

