// Secure Express.js application with comprehensive error handling and input validation
// Enhanced for security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ========== SECURITY MIDDLEWARE SETUP ==========

// 1. Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS configuration - restrict to trusted origins
const allowedOrigins = process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [];
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin || allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. Request parsing with limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// 5. Logging
app.use(morgan('combined')); // Logs all requests

// ========== VALIDATION MIDDLEWARE ==========

// Centralized validation error handler
const validate = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (errors.isEmpty()) {
      return next();
    }

    res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
        value: err.value
      }))
    });
  };
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';

    Error.captureStackTrace(this, this.constructor);
  }
}

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Cannot ${req.method} ${req.originalUrl}`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (but don't expose details in production)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Set default status code
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';

  // Don't expose error details in production for non-operational errors
  if (process.env.NODE_ENV === 'production' && !err.isOperational) {
    err.message = 'Internal server error';
  }

  // Send error response
  res.status(err.statusCode).json({
    success: false,
    status: err.status,
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint with validation
app.get('/health', validate([
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
]), asyncHandler(async (req, res) => {
  try {
    const { detailed } = req.query;

    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
    };

    if (detailed === 'true') {
      healthData.detailed = {
        nodeVersion: process.version,
        platform: process.platform,
        pid: process.pid,
      };
    }

    res.json({
      success: true,
      data: healthData
    });
  } catch (error) {
    throw new AppError('Health check failed', 503);
  }
}));

// Users endpoint with input validation and sanitization
app.get('/users', validate([
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer'),
  query('search').optional().trim().escape() // Sanitize search input
]), asyncHandler(async (req, res) => {
  const { limit = 10, offset = 0, search } = req.query;

  // Sample user data (in production, this would come from a database)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
