    { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'admin' },
  ];

  // Apply filtering if search parameter is provided
  let filteredUsers = users;
  if (search) {
    const searchLower = search.toLowerCase();
    filteredUsers = users.filter(user => 
      user.name.toLowerCase().includes(searchLower) || 
      user.email.toLowerCase().includes(searchLower)
    );
  }

  // Apply pagination
  const paginatedUsers = filteredUsers.slice(parseInt(offset), parseInt(offset) + parseInt(limit));

  res.json({
    success: true,
    data: {
      users: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: (parseInt(offset) + parseInt(limit)) < filteredUsers.length
      }
    }
  });
}));

// User detail endpoint with parameter validation
app.get('/users/:id', validate([
  param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer')
]), asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id);

  // In production, this would be a database lookup
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    throw new AppError('User not found', 404);
  }

  // Never expose sensitive fields like passwords, tokens, etc.
  const safeUser = {
    id: user.id,
    name: user.name,
    email: user.email,
    // role: user.role // Consider if role should be exposed based on authorization
  };

  res.json({
    success: true,
    data: safeUser
  });
}));

// Example POST endpoint with comprehensive validation
app.post('/users', validate([
  body('name').trim().notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces')
    .escape(), // Sanitize input

  body('email').trim().notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(), // Normalize email format

  body('age').optional().isInt({ min: 1, max: 120 }).withMessage('Age must be between 1 and 120'),

  body('role').optional().isIn(['user', 'admin', 'moderator']).withMessage('Invalid role'),
]), asyncHandler(async (req, res) => {
  const { name, email, age, role } = req.body;

  // In production, this would save to a database
  // Always hash passwords before storing!

  const newUser = {
    id: Date.now(), // Temporary ID
    name,
    email,
    age: age || null,
    role: role || 'user',
    createdAt: new Date().toISOString()
  };

  // Simulate data validation that might fail
  if (email.includes('test')) {
    throw new AppError('Test emails are not allowed', 400);
  }

  res.status(201).json({
    success: true,
    message: 'User created successfully',
    data: {
      id: newUser.id,
      name: newUser.name,
      email: newUser.email,
      createdAt: newUser.createdAt
    }
  });
}));

// ========== SECURITY MONITORING ENDPOINT ==========
// (Kept simple for this example - in production use proper monitoring tools)

app.get('/security/headers', (req, res) => {
  const headers = {
    'Content-Security-Policy': res.get('Content-Security-Policy'),
    'Strict-Transport-Security': res.get('Strict-Transport-Security'),
    'X-Frame-Options': res.get('X-Frame-Options'),
    'X-Content-Type-Options': res.get('X-Content-Type-Options'),
    'X-DNS-Prefetch-Control': res.get('X-DNS-Prefetch-Control'),
    'X-Download-Options': res.get('X-Download-Options'),
    'X-Permitted-Cross-Domain-Policies': res.get('X-Permitted-Cross-Domain-Policies'),
  };

  res.json({
    success: true,
    data: headers
  });
});

// ========== SERVER SETUP ==========

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Health check available at: http://localhost:${PORT}/health`);
});

// Handle graceful shutdown
