const express = require('express');
const app = express();

// ========== BASIC SECURITY SETTINGS ==========

// 1. Set security headers manually (basic protection without helmet)
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable strict transport security (for HTTPS)
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Prevent cross-site scripting
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Control referrer information
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});

// 2. Limit request body size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. Basic request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - IP: ${req.ip}`);
  next();
});

// ========== INPUT VALIDATION FUNCTIONS ==========

// Simple validation helpers
const validators = {
  isEmail: (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  },

  isInteger: (str, min = 1, max = 1000) => {
    const num = parseInt(str, 10);
    return !isNaN(num) && num >= min && num <= max;
  },

  isAlphaNumeric: (str, min = 1, max = 50) => {
    const regex = /^[a-zA-Z0-9\s\-_]+$/;
    return regex.test(str) && str.length >= min && str.length <= max;
  },

  sanitize: (str) => {
    if (typeof str !== 'string') return str;
    return str.trim().replace(/[<>]/g, '');
  }
};

// Validation middleware
const validateQueryParams = (rules) => {
  return (req, res, next) => {
    const errors = [];

    for (const [param, rule] of Object.entries(rules)) {
      const value = req.query[param];

      if (rule.required && (value === undefined || value === '')) {
        errors.push(`${param} is required`);
        continue;
      }

      if (value !== undefined && value !== '') {
        if (rule.type === 'email' && !validators.isEmail(value)) {
          errors.push(`${param} must be a valid email`);
        } else if (rule.type === 'integer' && !validators.isInteger(value, rule.min, rule.max)) {
          errors.push(`${param} must be an integer between ${rule.min || 1} and ${rule.max || 1000}`);
        } else if (rule.type === 'alphanumeric' && !validators.isAlphaNumeric(value, rule.min, rule.max)) {
          errors.push(`${param} must contain only letters, numbers, spaces, hyphens, and underscores`);
        }

        // Sanitize input
        if (rule.sanitize) {
          req.query[param] = validators.sanitize(value);
        }
      }
    }

    if (errors.length > 0) {
      return res.status(400).json({
        success: false,
        errors: errors
      });
    }

    next();
  };
};

// ========== ERROR HANDLING ==========

// Custom error class
