// Secure Express.js application with improved error handling and input validation
// Focused on security best practices

const express = require('express');
const app = express();

// ================= SECURITY IMPROVEMENTS =================

// 1. Basic Security Headers
app.use((req, res, next) => {
  // Protect against clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection in older browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Control referrer information
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});

// 2. Request size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));

// 3. Global Error Handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Never expose error details to clients in production
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: 'Internal server error'
  });
});

// ================= INPUT VALIDATION FUNCTIONS =================

// Helper functions for input validation
const validators = {
  isBooleanString: (str) => ['true', 'false'].includes(String(str).toLowerCase()),

  isPositiveInteger: (str, max = 100) => {
    const num = parseInt(str, 10);
    return !isNaN(num) && num > 0 && num <= max;
  },

  isNonNegativeInteger: (str) => {
    const num = parseInt(str, 10);
    return !isNaN(num) && num >= 0;
  },

  sanitizeString: (str) => {
    if (typeof str !== 'string') return str;
    return str.trim().replace(/[<>]/g, '');
  }
};

// ================= IMPROVED ROUTES WITH VALIDATION =================

// Health endpoint with query parameter validation
app.get('/health', (req, res) => {
  // Validate 'detailed' query parameter
  if (req.query.detailed && !validators.isBooleanString(req.query.detailed)) {
    return res.status(400).json({
      error: 'Invalid parameter',
      message: 'detailed must be "true" or "false"'
    });
  }

  const response = {
    status: 'ok',
    timestamp: new Date().toISOString()
  };

  if (req.query.detailed === 'true') {
    response.details = {
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };
  }

  res.json(response);
});

// Users endpoint with pagination and search validation
app.get('/users', (req, res) => {
  const errors = [];

  // Validate 'limit' parameter
  if (req.query.limit && !validators.isPositiveInteger(req.query.limit, 100)) {
    errors.push('limit must be a positive integer between 1 and 100');
  }

  // Validate 'offset' parameter
  if (req.query.offset && !validators.isNonNegativeInteger(req.query.offset)) {
    errors.push('offset must be a non-negative integer');
  }

  // Return validation errors
  if (errors.length > 0) {
    return res.status(400).json({
      error: 'Validation failed',
      messages: errors
    });
  }

  // Apply defaults and sanitize
  const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
  const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;
  const search = req.query.search ? validators.sanitizeString(req.query.search) : '';

  // Sample user data (in production, this would come from a database)
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
  ];

  // Apply search filter
  let filteredUsers = users;
  if (search) {
    const searchLower = search.toLowerCase();
    filteredUsers = users.filter(user => 
      user.name.toLowerCase().includes(searchLower) || 
      user.email.toLowerCase().includes(searchLower)
    );
  }

  // Apply pagination
  const paginatedUsers = filteredUsers.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      total: filteredUsers.length,
      limit: limit,
      offset: offset,
      hasMore: offset + limit < filteredUsers.length
    }
  });
});

// ================= ENHANCED ERROR HANDLING =================

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// ================= SERVER SETUP =================

const PORT = 3000;
app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
  console.log('Endpoints available:');
  console.log(`  GET  /health - Health check (optional: ?detailed=true)`);
  console.log(`  GET  /users - List users (optional: ?limit=10&offset=0&search=...)`);
});

module.exports = app;

