// Secure application with comprehensive error handling and input validation
// Security-focused Express.js application with best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const expressSanitizer = require('express-sanitizer');

// If dependencies aren't installed, you'll need to install them:
// npm install express helmet express-rate-limit cors express-sanitizer

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Helmet.js - Sets various security headers
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            scriptSrc: ["'self'"],
            styleSrc: ["'self'"],
            imgSrc: ["'self'", "data:"],
            connectSrc: ["'self'"],
            fontSrc: ["'self'"],
            objectSrc: ["'none'"],
            mediaSrc: ["'self'"],
            frameSrc: ["'none'"],
        },
    },
    crossOriginEmbedderPolicy: false, // Reduce for certain use cases
}));

// 2. CORS Configuration - Restrict origins in production
app.use(cors({
    origin: process.env.NODE_ENV === 'production' ? ['https://yourdomain.com'] : '*',
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400, // 24 hours
}));

// 3. Rate limiting - Prevent DoS attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});

app.use(limiter);

// 4. Body parsing with limits - Prevent large payload attacks
app.use(express.json({
    limit: '10kb', // Limit JSON payload size
    verify: (req, res, buf) => {
        try {
            JSON.parse(buf); // Validate JSON format
        } catch (e) {
            throw new Error('Invalid JSON format');
        }
    }
}));

app.use(express.urlencoded({
    extended: true,
    limit: '10kb',
    parameterLimit: 100 // Limit number of parameters
}));

// 5. Input sanitization middleware
app.use(expressSanitizer());

// ====================
// CUSTOM VALIDATION MIDDLEWARE
// ====================

// Input validation middleware
const validateInput = (req, res, next) => {
    // Check for common injection patterns
    const containsSQLInjection = (input) => {
        const sqlPatterns = [
            /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION|EXEC|ALTER)\b)/i,
            /(\b(OR|AND)\s+['\d]+=['\d]+\b)/i,
            /(--|\/\*|\*\/)/gi
        ];
        return sqlPatterns.some(pattern => pattern.test(input));
    };

    const containsXSS = (input) => {
        const xssPatterns = [
            /<(\s*script[^>]*)(>|.*>)/gi,
            /javascript:/gi,
            /on\w+\s*=/gi,
            /data:/gi,
            /vbscript:/gi
        ];
        return xssPatterns.some(pattern => pattern.test(input));
    };

    // Validate all incoming data
    const validateData = (data, path = '') => {
        if (typeof data === 'string') {
            if (containsSQLInjection(data)) {
                throw new Error(`SQL injection detected in ${path}`);
            }
            if (containsXSS(data)) {
                throw new Error(`XSS detected in ${path}`);
            }
            if (data.length > 1000) {
                throw new Error(`Input too long in ${path}`);
            }
        } else if (typeof data === 'object' && data !== null) {
            for (const [key, value] of Object.entries(data)) {
                validateData(value, path ? `${path}.${key}` : key);
            }
        }
    };

    try {
        // Validate query parameters
        if (req.query && Object.keys(req.query).length > 0) {
            validateData(req.query, 'query');
        }

        // Validate body parameters
        if (req.body && Object.keys(req.body).length > 0) {
            validateData(req.body, 'body');
        }

        // Validate URL parameters
        if (req.params && Object.keys(req.params).length > 0) {
            validateData(req.params, 'params');
        }

        next();
    } catch (error) {
        // Log the security event
        console.error(`Security Alert - ${req.ip}: ${error.message}`);

        // Return generic error message to avoid leaking information
        res.status(400).json({
            error: 'Invalid input detected',
            requestId: req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9)
        });
    }
};

app.use(validateInput);

// ====================
// ERROR HANDLING MIDDLEWARE
// ====================

// Central error handling middleware
const errorHandler = (err, req, res, next) => {
    // Determine error type and status code
    let statusCode = 500;
    let errorMessage = 'Internal Server Error';

    // Classify errors
    if (err.name === 'ValidationError') {
        statusCode = 400;
        errorMessage = err.message;
    } else if (err.name === 'UnauthorizedError') {
        statusCode = 401;
        errorMessage = 'Unauthorized';
    } else if (err.name === 'ForbiddenError') {
        statusCode = 403;
        errorMessage = 'Forbidden';
    } else if (err.name === 'NotFoundError') {
        statusCode = 404;
        errorMessage = 'Resource not found';
    } else if (err.name === 'RateLimitError') {
        statusCode = 429;
        errorMessage = 'Too many requests';
    }

    // Log error details (in production, use proper logging)
    console.error(`Error ${statusCode}: ${err.message}`);
    console.error(`Stack trace: ${err.stack}`);
    console.error(`Request: ${req.method} ${req.originalUrl}`);
    console.error(`IP: ${req.ip}`);

    // Don't expose stack traces in production
    const response = {
        error: errorMessage,
        status: statusCode,
        timestamp: new Date().toISOString(),
        requestId: req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9)
    };

    // Include validation errors if they exist
    if (err.errors && Array.isArray(err.errors)) {
        response.validationErrors = err.errors;
    }

    res.status(statusCode).json(response);
};

app.use(errorHandler);

// ====================
// APPLICATION ROUTES
// ====================

// Health check endpoint with validation
app.get('/health', (req, res) => {
    try {
        // Validate any query parameters if present
        if (req.query && Object.keys(req.query).length > 0) {
            // Additional query parameter validation
            const allowedParams = ['detailed', 'checks'];
            for (const param of Object.keys(req.query)) {
                if (!allowedParams.includes(param)) {
                    throw new Error(`Invalid parameter: ${param}`);
                }
            }
        }

        res.json({
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
            environment: process.env.NODE_ENV || 'development'
        });
    } catch (error) {
        // Pass error to middleware
        error.name = 'ValidationError';
        throw error;
    }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
    try {
        // Validate query parameters
        const { page = '1', limit = '10' } = req.query;

        // Validate numeric parameters
        if (isNaN(parseInt(page)) || parseInt(page) < 1) {
            throw new Error('Page must be a positive integer');
        }

        if (isNaN(parseInt(limit)) || parseInt(limit) < 1 || parseInt(limit) > 100) {
            throw new Error('Limit must be between 1 and 100');
        }

        // Mock user data
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        // Pagination simulation
        const pageNum = parseInt(page);
        const limitNum = parseInt(limit);
        const startIndex = (pageNum - 1) * limitNum;
        const paginatedUsers = users.slice(startIndex, startIndex + limitNum);

        res.json({
            users: paginatedUsers,
            pagination: {
                page: pageNum,
                limit: limitNum,
                totalPages: Math.ceil(users.length / limitNum),
                totalUsers: users.length
            },
            metadata: {
                timestamp: new Date().toISOString(),
                requestId: req.headers['x-request-id'] || Math.random().toString(36).substr(2, 9)
            }
        });
    } catch (error) {
        // Add error classification
        error.name = 'ValidationError';
        next(error);
    }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
    res.status(404).json({
        error: 'Route not found',
        method: req.method,
        path: req.originalUrl,
        timestamp: new Date().toISOString()
    });
});

// ====================
// SERVER CONFIGURATION
// ====================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Security features enabled:`);
    console.log(`- Helmet.js security headers`);
    console.log(`- CORS protection`);
    console.log(`- Rate limiting (100 requests/15 min per IP)`);
    console.log(`- Input validation & sanitization`);
    console.log(`- Request size limits (10KB)`);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    // In production, you might want to restart the process
    if (process.env.NODE_ENV === 'production') {
        process.exit(1);
    }
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

