// Enhanced application with comprehensive error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const { sanitize } = require('express-validator');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();

// ==================== Security Middleware ====================

// Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS (adjust based on your requirements)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting for API endpoints
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use('/api/', apiLimiter);

// Request size limits
app.use(express.json({ limit: '10kb' })); // JSON body limit
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // URL-encoded body limit

// Logging middleware
if (process.env.NODE_ENV === 'production') {
  // Create a write stream for access logs in production
  const accessLogStream = fs.createWriteStream(
    path.join(__dirname, 'access.log'),
    { flags: 'a' }
  );
  app.use(morgan('combined', { stream: accessLogStream }));
} else {
  app.use(morgan('dev'));
}

// ==================== Custom Error Classes ====================

class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(errors) {
    super('Validation failed', 400);
    this.errors = errors;
  }
}

// ==================== Utility Functions ====================

const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    const error = new ValidationError(errors.array());
    return next(error);
  }
  next();
};

const catchAsync = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ==================== Error Handling Middleware ====================

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Default values for error
  err.statusCode = err.statusCode || 500;
  err.status = err.status || 'error';
  err.message = err.message || 'Something went wrong';

  // Log error in development or if it's not operational
  if (process.env.NODE_ENV === 'development' || !err.isOperational) {
    console.error('Error:', {
      message: err.message,
      stack: err.stack,
      statusCode: err.statusCode,
      path: req.path,
      method: req.method,
      body: req.body,
      query: req.query,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });
  }

  // Don't expose internal error details to client in production
  if (process.env.NODE_ENV === 'production' && !err.isOperational) {
    err.message = 'An unexpected error occurred';
  }

  // Handle validation errors specially
  if (err instanceof ValidationError) {
    return res.status(err.statusCode).json({
      status: 'error',
      message: err.message,
      errors: err.errors.map(e => ({
        field: e.path,
        message: e.msg,
        value: e.value
      })),
      timestamp: new Date().toISOString()
    });
  }

  // Handle other errors
  res.status(err.statusCode).json({
    status: err.status,
    message: err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// ==================== Routes with Validation ====================

// Health check endpoint with input validation
app.get('/health', 
  [
    query('verbose').optional().isBoolean().toBoolean(),
    query('checks').optional().isArray()
  ],
  validateInput,
  (req, res) => {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    // Add verbose information if requested
    if (req.query.verbose) {
      healthData.detailed = {
        nodeVersion: process.version,
        platform: process.platform,
        pid: process.pid,
        cwd: process.cwd()
      };
    }

    res.json(healthData);
  }
);

// Users endpoint with comprehensive validation
app.get('/users',
  apiLimiter, // Apply rate limiting specifically to this endpoint
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('email').optional().isEmail().normalizeEmail(),
    query('name').optional().isString().trim().escape(),
    query('active').optional().isBoolean().toBoolean(),
    query('sort').optional().isIn(['id', 'name', 'email']),
    query('order').optional().isIn(['asc', 'desc'])
  ],
  validateInput,
  catchAsync(async (req, res, next) => {
    try {
      // Simulate database query with pagination
      const page = req.query.page || 1;
      const limit = req.query.limit || 10;
      const offset = (page - 1) * limit;

      // In a real application, this would query a database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', active: true },
        { id: 2, name: 'Bob', email: 'bob@example.com', active: false },
      ];

      // Apply filters based on query parameters
      let filteredUsers = [...users];

      if (req.query.email) {
        filteredUsers = filteredUsers.filter(user => 
          user.email.includes(req.query.email)
        );
      }

      if (req.query.name) {
        filteredUsers = filteredUsers.filter(user => 
          user.name.toLowerCase().includes(req.query.name.toLowerCase())
        );
      }

      if (req.query.active !== undefined) {
        filteredUsers = filteredUsers.filter(user => 
          user.active === req.query.active
        );
      }

      // Apply sorting
      if (req.query.sort) {
        const order = req.query.order === 'desc' ? -1 : 1;
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1 * order;
          if (a[req.query.sort] > b[req.query.sort]) return 1 * order;
          return 0;
        });
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);
      const totalUsers = filteredUsers.length;
      const totalPages = Math.ceil(totalUsers / limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: totalUsers,
          totalPages,
          hasNextPage: page < totalPages,
          hasPrevPage: page > 1
        },
        meta: {
          timestamp: new Date().toISOString(),
          filteredCount: filteredUsers.length,
          originalCount: users.length
        }
      });
    } catch (error) {
      next(new AppError('Failed to fetch users', 500));
    }
  })
);

// Example POST endpoint with validation
app.post('/users',
  [
    body('name')
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .trim()
      .escape(),
    body('email')
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Please provide a valid email')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120')
      .toInt(),
    body('active')
      .optional()
      .isBoolean().withMessage('Active must be a boolean value')
      .toBoolean(),
    body('tags')
      .optional()
      .isArray().withMessage('Tags must be an array')
  ],
  validateInput,
  catchAsync(async (req, res, next) => {
    try {
      // In a real application, save to database
      const newUser = {
        id: Date.now(), // Temporary ID
        ...req.body,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      // Remove any fields that shouldn't be returned
      delete newUser.password; // If password was in the body

      res.status(201).json({
        message: 'User created successfully',
        data: newUser,
        timestamp: new Date().toISOString()
      });
    } catch (error) {
      next(new AppError('Failed to create user', 500));
    }
  })
);

// ==================== 404 Handler ====================

app.all('*', (req, res, next) => {
  next(new AppError(`Can't find ${req.originalUrl} on this server!`, 404));
});

// ==================== Environment Validation ====================

const validateEnvironment = () => {
  const requiredEnvVars = [];

  // Check if all required environment variables are present
  const missingEnvVars = requiredEnvVars.filter(
    envVar => !process.env[envVar]
  );

  if (missingEnvVars.length > 0 && process.env.NODE_ENV === 'production') {
    console.error('Missing required environment variables:', missingEnvVars);
    return new Error('Missing required environment variables');
  }

  // Validate known environment variables
  if (process.env.PORT) {
    const port = parseInt(process.env.PORT, 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      console.error('Invalid PORT environment variable');
      return new Error('Invalid PORT environment variable');
    }
  }

  return null;
};

// ==================== Server Initialization ====================

const startServer = () => {
  try {
    // Validate environment variables
    const envError = validateEnvironment();
    if (envError) {
      console.error('Environment validation failed:', envError.message);
      process.exit(1);
    }

    const PORT = process.env.PORT || 3000;

    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
      console.log('Security middleware enabled:', {
        helmet: '✓',
        cors: '✓',
        rateLimiting: '✓',
        requestSizeLimits: '✓',
        inputValidation: '✓',
        logging: '✓',
        errorHandling: '✓'
      });
    });

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      // In production, you might want to exit the process
      if (process.env.NODE_ENV === 'production') {
        process.exit(1);
      }
    });

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('Uncaught Exception:', error);
      // In production, you might want to exit the process
      if (process.env.NODE_ENV === 'production') {
        process.exit(1);
      }
    });

  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Start the server if this file is run directly
if (require.main === module) {
  startServer();
} else {
  // Export for testing
  module.exports = {
    app,
    AppError,
    ValidationError,
    validateInput,
    catchAsync,
    validateEnvironment,
    startServer
  };
}

