const { body, query, validationResult } = require('express-validator');

const app = express();

// ==================== Security Middleware ====================

// Set basic security headers
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Enable XSS protection in browsers
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});

// Request size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== Input Validation Helper ====================

const validateInput = (validations) => {
  return async (req, res, next) => {
    try {
      // Run validations
      await Promise.all(validations.map(validation => validation.run(req)));

      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          message: 'Validation failed',
          errors: errors.array().map(err => ({
            field: err.path,
            message: err.msg,
            value: err.value
          })),
          timestamp: new Date().toISOString()
        });
      }

      next();
    } catch (error) {
      console.error('Validation error:', error);
      res.status(500).json({
        status: 'error',
        message: 'Internal server error during validation',
        timestamp: new Date().toISOString()
      });
    }
  };
};

// ==================== Error Handling Middleware ====================

// Central error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine response based on error type
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      status: 'error',
      message: 'Input validation failed',
      timestamp: new Date().toISOString()
    });
  }

  // Don't leak internal errors in production
  const isProduction = process.env.NODE_ENV === 'production';
  const errorMessage = isProduction 
    ? 'An unexpected error occurred. Please try again later.'
    : err.message;

  res.status(500).json({
    status: 'error',
    message: errorMessage,
    ...(!isProduction && { stack: err.stack }),
    timestamp: new Date().toISOString()
  });
});

// Handle async errors
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// ==================== Routes with Validation ====================

// Health check endpoint with validation
app.get('/health', 
  validateInput([
    query('verbose').optional().isBoolean().toBoolean(),
    query('checks').optional().isString().isIn(['all', 'basic', 'none'])
  ]),
  (req, res) => {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Only add verbose info if explicitly requested
    if (req.query.verbose === true) {
      healthData.detailed = {
        memory: process.memoryUsage(),
        nodeVersion: process.version
      };
    }

    res.json(healthData);
  }
);

// Users endpoint with comprehensive validation
app.get('/users',
  validateInput([
    query('limit').optional().isInt({ min: 1, max: 50 }).toInt(),
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('sortBy').optional().isIn(['id', 'name', 'email']),
    query('order').optional().isIn(['asc', 'desc']),
    query('search').optional().isString().trim().escape()
  ]),
  asyncHandler(async (req, res) => {
    try {
      // Validate and sanitize input
      const limit = req.query.limit || 10;
      const page = req.query.page || 1;
      const offset = (page - 1) * limit;

      // Hardcoded user data (in production, this would come from a database)
      let users = [
        { 
          id: 1, 
          name: 'Alice Johnson', 
          email: 'alice.johnson@example.com',
          createdAt: new Date('2023-01-15').toISOString(),
          status: 'active'
        },
        { 
          id: 2, 
          name: 'Bob Smith', 
          email: 'bob.smith@example.com',
          createdAt: new Date('2023-02-20').toISOString(),
          status: 'active'
        },
        { 
          id: 3, 
          name: 'Charlie Brown', 
          email: 'charlie.brown@example.com',
          createdAt: new Date('2023-03-25').toISOString(),
          status: 'inactive'
        },
        { 
          id: 4, 
          name: 'Diana Prince', 
          email: 'diana.prince@example.com',
          createdAt: new Date('2023-04-10').toISOString(),
          status: 'active'
        }
      ];

      // Apply search filter if provided
      if (req.query.search) {
        const searchTerm = req.query.search.toLowerCase();
        users = users.filter(user => 
          user.name.toLowerCase().includes(searchTerm) ||
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Apply sorting if specified
      if (req.query.sortBy) {
        const order = req.query.order === 'desc' ? -1 : 1;
        users.sort((a, b) => {
          if (a[req.query.sortBy] < b[req.query.sortBy]) return -1 * order;
          if (a[req.query.sortBy] > b[req.query.sortBy]) return 1 * order;
          return 0;
        });
      }

      // Apply pagination
      const totalUsers = users.length;
      const totalPages = Math.ceil(totalUsers / limit);
      const paginatedUsers = users.slice(offset, offset + limit);

      // Validate pagination parameters
      if (page > totalPages && totalPages > 0) {
        return res.status(400).json({
          status: 'error',
          message: `Invalid page number. Maximum page is ${totalPages}`,
          timestamp: new Date().toISOString()
        });
      }

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          totalItems: totalUsers,
          totalPages,
          hasNextPage: page < totalPages,
          hasPreviousPage: page > 1
        },
        meta: {
          timestamp: new Date().toISOString(),
          itemCount: paginatedUsers.length
        }
      });

    } catch (error) {
      // Log the error for debugging
      console.error('Error fetching users:', error);
      throw new Error('Failed to fetch users. Please try again later.');
    }
  })
);

// Example POST endpoint for creating users
app.post('/users',
  validateInput([
    body('name')
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
      .trim()
      .escape(),
    body('email')
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Please provide a valid email address')
      .normalizeEmail(),
    body('age')
      .optional()
      .isInt({ min: 13, max: 120 }).withMessage('Age must be between 13 and 120')
      .toInt()
  ]),
  asyncHandler(async (req, res) => {
    try {
      const { name, email, age } = req.body;

      // Additional business logic validation
      if (name.includes('<script>') || name.includes('javascript:')) {
        return res.status(400).json({
          status: 'error',
          message: 'Invalid characters in name field',
          timestamp: new Date().toISOString()
        });
      }

      // In a real application, you would:
      // 1. Hash the password (not shown in this example)
      // 2. Validate email uniqueness
      // 3. Save to database

      const newUser = {
        id: Date.now(), // Temporary ID for demo
        name: name,
        email: email,
        age: age || null,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      res.status(201).json({
        status: 'success',
        message: 'User created successfully',
        data: newUser,
        timestamp: new Date().toISOString()
      });

    } catch (error) {
      console.error('Error creating user:', error);
      throw new Error('Failed to create user. Please try again later.');
    }
  })
);

// ==================== 404 Handler ====================

app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`,
    timestamp: new Date().toISOString(),
    suggestion: 'Check the API documentation for available endpoints'
  });
});

// ==================== Server Configuration ====================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Validate PORT is a valid number
const portNumber = parseInt(PORT, 10);
if (isNaN(portNumber) || portNumber < 1 || portNumber > 65535) {
  console.error(`Invalid PORT specified: ${PORT}`);
  process.exit(1);
}

// Start server with error handling
try {
  const server = app.listen(PORT, HOST, () => {
    console.log(`Server running at http://${HOST}:${PORT}`);
    console.log('Available endpoints:');
    console.log('  GET  /health - Health check');
    console.log('  GET  /users - Get users list (with pagination & search)');
    console.log('  POST /users - Create new user');
    console.log('\nSecurity features enabled:');
    console.log('  ✓ Input validation and sanitization');
    console.log('  ✓ Request size limits');
    console.log('  ✓ Security headers');
    console.log('  ✓ Centralized error handling');
    console.log('  ✓ Async error handling');
  });

  // Graceful shutdown handlers
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('HTTP server closed.');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Could not close connections in time, forcefully shutting down');
      process.exit(1);
    }, 10000);
  };

  // Handle termination signals
  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });

} catch (error) {
  console.error('Failed to start server:', error);
  process.exit(1);
}

module.exports = app;

# Security Improvements and Best Practices for app.js

## Current Issues Identified in Original app.js

1. **Missing Error Handling**
   - No centralized error handling middleware
   - Unhandled exceptions could crash the server
   - No graceful error responses to clients

2. **No Input Validation**
   - Query parameters and request bodies are not validated
   - Risk of NoSQL injection, SQL injection (if connected to DB)
   - Potential for malicious data processing

3. **Security Headers Missing**
   - No protection against clickjacking (X-Frame-Options)
   - No XSS protection headers
   - No MIME type sniffing prevention

4. **No Request Size Limits**
   - Vulnerable to DoS attacks with large payloads

5. **Poor Logging**
   - Basic console.log without structured logging
   - No request/response logging
   - No error tracking

6. **Missing Rate Limiting**
   - No protection against brute force attacks

7. **No CORS Configuration**
   - Cross-origin requests are not controlled

## Recommended Improvements

### 1. Install Required Dependencies

```bash
npm install express-validator helmet cors express-rate-limit morgan
```

### 2. Essential Security Middleware

#### a. Set Security Headers
```javascript
// Using helmet for comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  }
}));
```

#### b. Request Size Limits
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

#### c. Rate Limiting
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
});
app.use('/api/', limiter);
```

### 3. Input Validation with express-validator

#### a. Validation Middleware
```javascript
const validateInput = (validations) => {
  return async (req, res, next) => {
    try {
      await Promise.all(validations.map(v => v.run(req)));
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          status: 'error',
          errors: errors.array()
        });
      }
      next();
    } catch (error) {
      res.status(500).json({ error: 'Validation error' });
    }
  };
};
```

#### b. Route-specific Validation
```javascript
app.get('/users',
  validateInput([
    query('limit').isInt({ min: 1, max: 100 }).toInt(),
    query('page').isInt({ min: 1 }).toInt(),
    query('search').optional().isString().trim().escape()
  ]),
  asyncHandler(async (req, res) => {
    // Your route logic
  })
);
```

### 4. Comprehensive Error Handling

#### a. Error Classes
```javascript
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.status = `${statusCode}`.startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
  }
}
```

#### b. Central Error Handler
```javascript
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    timestamp: new Date().toISOString()
  });

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    status: 'error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An error occurred' 
      : err.message
  });
});
```

#### c. Async Error Handler
```javascript
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};
```

### 5. Environment Variable Security

#### a. Validation
```javascript
const validateEnvironment = () => {
  const required = [];
  const missing = required.filter(envVar => !process.env[envVar]);

  if (missing.length > 0) {
    throw new Error(`Missing required env vars: ${missing.join(', ')}`);
  }

  // Validate specific variables
  if (process.env.PORT) {
    const port = parseInt(process.env.PORT, 10);
    if (port < 1 || port > 65535) {
      throw new Error('Invalid PORT');
    }
  }
};
```

### 6. Logging Best Practices

#### a. Structured Logging
```javascript
const logger = {
  info: (message, meta = {}) => {
    console.log(JSON.stringify({
      level: 'info',
      timestamp: new Date().toISOString(),
      message,
      ...meta
    }));
  },
  error: (message, error, meta = {}) => {
    console.error(JSON.stringify({
      level: 'error',
      timestamp: new Date().toISOString(),
      message,
      error: {
        message: error.message,
        stack: error.stack
      },
      ...meta
    }));
  }
};
```

#### b. Request Logging Middleware
```javascript
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    logger.info('Request completed', {
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      responseTime: Date.now() - startTime,
      ip: req.ip
    });
  });

  next();
});
```

### 7. Data Sanitization

```javascript
// Always sanitize user input
const sanitizeUserInput = (input) => {
  if (typeof input === 'string') {
    return input
      .trim()
      .replace(/<[^>]*>/g, '') // Remove HTML tags
      .replace(/javascript:/gi, '') // Remove javascript: protocol
      .replace(/on\w+="[^"]*"/gi, ''); // Remove event handlers
  }
  return input;
};
```

### 8. Additional Security Considerations

#### a. Session Security (if using sessions)
```javascript
app.use(session({
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'strict',
    maxAge: 24 * 60 * 60 * 1000 // 24 hours
  }
}));
```

#### b. HTTP to HTTPS Redirection (for production)
```javascript
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.headers['x-forwarded-proto'] !== 'https') {
      return res.redirect(`https://${req.headers.host}${req.url}`);
    }
    next();
  });
}
```

#### c. CORS Configuration
```javascript
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000'],
  credentials: true
}));
```

## Quick Wins for Immediate Implementation

1. **Add Basic Security Headers** (5 minutes)
2. **Implement Input Validation** (15 minutes)
3. **Set Up Central Error Handling** (10 minutes)
4. **Add Request Size Limits** (2 minutes)

## Production Checklist

- [ ] Implement rate limiting
- [ ] Configure CORS properly
- [ ] Set up structured logging
- [ ] Validate environment variables
- [ ] Implement graceful shutdown
- [ ] Add request/response logging
- [ ] Set up monitoring/alerting
- [ ] Regular security dependency updates
- [ ] Security headers audit
- [ ] Input validation coverage

## Critical Security Tips

1. **Never trust user input** - Always validate and sanitize
2. **Use parameterized queries** - If using a database, prevent SQL injection
3. **Store secrets securely** - Use environment variables, not code
4. **Keep dependencies updated** - Regularly check for security vulnerabilities
5. **Implement proper logging** - But be careful not to log sensitive data
6. **Use HTTPS in production** - Always with proper SSL/TLS configuration
7. **Regular security audits** - Both code and infrastructure

## Resources

- [OWASP Node.js Security Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [express-validator Documentation](https://express-validator.github.io/docs/)

