// Secure Express Application with enhanced error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config(); // Load environment variables

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Helmet.js - Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] // Production domains
    : ['http://localhost:3000', 'http://localhost:8080'], // Development domains
  optionsSuccessStatus: 200,
  credentials: true
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false
});
app.use('/api/', limiter); // Apply to API routes

// 4. Request parsing with security limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  verify: (req, res, buf) => {
    try {
      JSON.parse(buf); // Validate JSON syntax early
    } catch (e) {
      throw new Error('Invalid JSON payload');
    }
  }
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// 5. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ========== INPUT VALIDATION FUNCTIONS ==========

// Email validation regex
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// Sanitize user input
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Remove potential XSS payloads
  return input
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/javascript:/gi, '')
    .replace(/on\w+=/gi, '')
    .trim();
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// Global error handler
const errorHandler = (err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`);
  console.error(err.stack);

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't expose internal errors in production
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: {
      message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
    },
    timestamp: new Date().toISOString()
  });
};

// 404 handler
const notFoundHandler = (req, res, next) => {
  const error = new Error(`Route not found: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
};

// ========== VALIDATION MIDDLEWARE ==========

const validateUserInput = [
  body('name')
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .trim()
    .escape(), // HTML escape for security

  body('email')
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(), // Normalize email format

  body('age')
    .optional()
    .isInt({ min: 0, max: 120 }).withMessage('Age must be between 0 and 120'),

  body('password')
    .optional()
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
];

// ========== ROUTES WITH VALIDATION ==========

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(503).json({ 
      status: 'error', 
      message: 'Service temporarily unavailable' 
    });
  }
});

// Get users with input validation for query parameters
app.get('/users', [
  // Validate query parameters
  (req, res, next) => {
    const { limit, offset } = req.query;

    // Sanitize and validate numeric parameters
    if (limit) {
      const limitNum = parseInt(limit, 10);
      if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
        return res.status(400).json({
          success: false,
          error: 'Limit must be a number between 1 and 100'
        });
      }
      req.query.limit = limitNum;
    }

    if (offset) {
      const offsetNum = parseInt(offset, 10);
      if (isNaN(offsetNum) || offsetNum < 0) {
        return res.status(400).json({
          success: false,
          error: 'Offset must be a non-negative number'
        });
      }
      req.query.offset = offsetNum;
    }

    next();
  }
], (req, res, next) => {
  try {
    const { limit = 10, offset = 0 } = req.query;

    // Mock database query with validation
    const users = [
      { 
        id: 1, 
        name: sanitizeInput('Alice'), 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: sanitizeInput('Bob'), 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      success: true,
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Get user by ID with validation
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Validate ID parameter
    if (isNaN(userId) || userId <= 0) {
      const error = new Error('Invalid user ID');
      error.statusCode = 400;
      throw error;
    }

    // Mock response
    res.json({
      success: true,
      data: {
        id: userId,
        name: `User ${userId}`,
        email: `user${userId}@example.com`
      }
    });
  } catch (error) {
    next(error);
  }
});

// Create user with comprehensive validation
app.post('/users', validateUserInput, (req, res, next) => {
  try {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.statusCode = 400;
      error.validationErrors = errors.array();
      throw error;
    }

    const { name, email, age, password } = req.body;

    // Additional custom validation
    if (!validateEmail(email)) {
      const error = new Error('Invalid email format');
      error.statusCode = 400;
      throw error;
    }

    // Mock user creation
    const newUser = {
      id: Date.now(), // In real app, use database-generated ID
      name: sanitizeInput(name),
      email: email.toLowerCase(), // Normalize email
      age: age || null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    // In production: hash password before storing
    if (password) {
      newUser.passwordHash = `hashed_${password}`; // Replace with bcrypt.hash()
    }

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });

  } catch (error) {
    next(error);
  }
});

// ========== ERROR HANDLING SETUP ==========

// Apply not-found handler
app.use(notFoundHandler);

// Apply global error handler
app.use(errorHandler);

// ========== SERVER STARTUP ==========

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const startServer = () => {
  try {
    // Validate required environment variables
    const requiredEnvVars = ['NODE_ENV'];
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
      throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
    }

    app.listen(PORT, () => {
      console.log(`🚀 Server running on port ${PORT} in ${NODE_ENV} mode`);
      console.log(`📊 Health check: http://localhost:${PORT}/health`);
      console.log(`🔐 Security headers enabled`);
      console.log(`🛡️ Rate limiting active on API routes`);
    });

  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
};

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Performing graceful shutdown...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down...');
  process.exit(0);
});

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

module.exports = app;

// Quick test script to demonstrate security improvements

const app = require('./app_improved');

// Test cases demonstrating security improvements
const testCases = [
  {
    name: 'Test 1: Input Validation - Invalid Email',
    path: '/users',
