// Configuration dependency analysis
// Safe analysis without accessing sensitive files

const fs = require('fs');
const path = require('path');

function analyzeFile(filePath) {
    try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n');

        // Check for require/import statements
        const requires = lines.filter(line => line.includes('require('));
        const imports = lines.filter(line => line.includes('import '));

        // Check for process.env usage
        const envRefs = lines.filter(line => line.includes('process.env'));

        // Check for dotenv usage
        const dotenvRefs = lines.filter(line => line.includes('dotenv'));

        return {
            file: filePath,
            requires: requires.length,
            imports: imports.length,
            envVariables: envRefs.length,
            dotenvUsage: dotenvRefs.length > 0,
            sampleEnvRefs: envRefs.slice(0, 3) // Show max 3 examples
        };
    } catch (error) {
        return {
            file: filePath,
            error: error.message
        };
    }
}

function analyzeCodebase() {
    console.log('🔍 Configuration Dependency Analysis');
    console.log('=' .repeat(50));

    const files = ['app.js', 'app_improved.js'];

    let originalHasConfig = false;
    let improvedHasConfig = false;

    files.forEach(file => {
        if (fs.existsSync(file)) {
            const analysis = analyzeFile(file);
            console.log(`\n📄 ${file}:`);

            if (analysis.error) {
                console.log(`   ❌ Error: ${analysis.error}`);
            } else {
                console.log(`   📊 Lines with require(): ${analysis.requires}`);
                console.log(`   📊 Lines with import: ${analysis.imports}`);
                console.log(`   ⚙️  Environment variable references: ${analysis.envVariables}`);
                console.log(`   🔧 dotenv usage: ${analysis.dotenvUsage ? 'Yes' : 'No'}`);

                if (analysis.sampleEnvRefs.length > 0) {
                    console.log(`   📝 Sample env references:`);
                    analysis.sampleEnvRefs.forEach(ref => {
                        console.log(`     - ${ref.trim().substring(0, 60)}...`);
                    });
                }

                // Track which version has configuration
                if (file === 'app.js' && analysis.envVariables > 0) {
                    originalHasConfig = true;
                }
                if (file === 'app_improved.js' && analysis.envVariables > 0) {
                    improvedHasConfig = true;
                }
            }
        } else {
            console.log(`\n📄 ${file}: ❌ File not found`);
        }
    });

    console.log('\n' + '=' .repeat(50));
    console.log('📋 CONFIGURATION SUMMARY:');
    console.log('=' .repeat(50));

    if (!originalHasConfig && improvedHasConfig) {
        console.log('✅ Original app.js: No environment configuration needed');
        console.log('⚠️  Improved version: Adds configuration requirements');
        console.log('\n🔧 Migration would require:');
        console.log('   1. Setting up environment variables');
        console.log('   2. Creating .env files for different environments');
        console.log('   3. Updating deployment configuration');
    } else if (originalHasConfig && !improvedHasConfig) {
        console.log('⚠️  Original app.js: Has configuration dependencies');
        console.log('✅ Improved version: Removes configuration requirements');
    } else if (originalHasConfig && improvedHasConfig) {
        console.log('⚠️  Both versions have configuration dependencies');
        console.log('📝 Review compatibility before migration');
    } else {
        console.log('✅ Both versions are configuration-free');
    }

    console.log('\n💡 RECOMMENDATION:');
    console.log('If moving to production with the improved version:');
    console.log('1. Start with minimal .env file (NODE_ENV, PORT)');
    console.log('2. Add additional configuration as features are added');
    console.log('3. Use .env.example as template, never commit .env files');
}

// Run analysis if this file is executed directly
if (require.main === module) {
    analyzeCodebase();
}

module.exports = {
    analyzeCodebase,
    analyzeFile
};

