// Secure application with comprehensive error handling and input validation
// This is a secure version demonstrating security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { validationResult, query } = require('express-validator');
require('dotenv').config();

const app = express();

// ==================== SECURITY MIDDLEWARE ====================

// 1. Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
    },
  },
  crossOriginEmbedderPolicy: false,
}));

// 2. Enable CORS with proper configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3001'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 3. Apply rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 4. Basic security middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== ERROR HANDLERS ====================

// Generic error handler middleware
const errorHandler = (err, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${req.method} ${req.path}:`, {
    message: err.message,
    stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
    statusCode: err.statusCode || 500,
  });

  const statusCode = err.statusCode || 500;
  const response = {
    error: {
      message: statusCode === 500 ? 'Internal Server Error' : err.message,
      timestamp: new Date().toISOString(),
    },
  };

  // Don't leak stack trace in production
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.error.stack = err.stack;
  }

  res.status(statusCode).json(response);
};

// Not found handler
const notFoundHandler = (req, res, next) => {
  const error = new Error(`Resource not found: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
};

// ==================== VALIDATION UTILITIES ====================

// Sanitize input data
const sanitizeInput = (input) => {
  if (typeof input === 'string') {
    // Remove potentially dangerous characters
    return input
      .replace(/[<>]/g, '') // Remove HTML tags
      .replace(/javascript:/gi, '') // Remove javascript: protocol
      .replace(/on\w+="/gi, '') // Remove event handlers
      .trim();
  }
  return input;
};

// Validate email format
const validateEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// Validate ID format (numeric)
const validateId = (id) => {
  return /^\d+$/.test(id) && parseInt(id, 10) > 0;
};

// ==================== ROUTES WITH VALIDATION ====================

app.get('/health', [
  // Input validation for query parameters
  query('detailed').optional().isBoolean().toBoolean(),
  query('format').optional().isIn(['json', 'plain']),
], (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.statusCode = 400;
      error.errors = errors.array();
      return next(error);
    }

    const { detailed = false, format = 'json' } = req.query;

    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    if (detailed) {
      healthData.memory = process.memoryUsage();
      healthData.env = process.env.NODE_ENV || 'development';
    }

    if (format === 'plain') {
      res.set('Content-Type', 'text/plain');
      res.send(`Status: ${healthData.status}\nTimestamp: ${healthData.timestamp}`);
    } else {
      res.json(healthData);
    }
  } catch (error) {
    next(error);
  }
});

app.get('/users', [
  // Validate query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('search').optional().isString().trim().escape(),
], (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      const error = new Error('Validation failed');
      error.statusCode = 400;
      error.errors = errors.array();
      return next(error);
    }

    const { limit = 10, page = 1, search = '' } = req.query;

    // Sanitize search input
    const sanitizedSearch = sanitizeInput(search);

    // Sample users data
    const sampleUsers = [
      { id: 1, name: 'Alice Johnson', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob Smith', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Carol Davis', email: 'carol@example.com', role: 'user' },
      { id: 4, name: 'David Wilson', email: 'david@example.com', role: 'user' },
      { id: 5, name: 'Eve Brown', email: 'eve@example.com', role: 'moderator' },
    ];

    // Filter users based on search (for demo purposes)
    let filteredUsers = sampleUsers;
    if (sanitizedSearch) {
      filteredUsers = sampleUsers.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
        user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );
    }

    // Pagination logic
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    const response = {
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        page: parseInt(page),
        limit: parseInt(limit),
        pages: Math.ceil(filteredUsers.length / limit),
      },
      meta: {
        timestamp: new Date().toISOString(),
        search: sanitizedSearch || null,
      },
    };

    res.json(response);
  } catch (error) {
    next(error);
  }
});

// New secure endpoint example with POST and validation
app.post('/users', [
  // Validate request body
  query().custom(() => {
    // Ensure this is a POST request
    return true;
  }),
], (req, res, next) => {
  try {
    // In a real application, you would validate the request body
    // For this example, we'll demonstrate proper error handling

    const { name, email } = req.body;

    if (!name || !email) {
      const error = new Error('Name and email are required');
      error.statusCode = 400;
      return next(error);
    }

    if (!validateEmail(email)) {
      const error = new Error('Invalid email format');
      error.statusCode = 400;
      return next(error);
    }

    // Sanitize inputs
    const sanitizedName = sanitizeInput(name);
    const sanitizedEmail = sanitizeInput(email);

    // In a real app, save to database here
    const newUser = {
      id: Math.floor(Math.random() * 1000) + 6, // Simulated ID
      name: sanitizedName,
      email: sanitizedEmail,
      role: 'user',
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  } catch (error) {
    next(error);
  }
});

// Secure user by ID endpoint
app.get('/users/:id', [
  // Validate ID parameter
  query().custom((value, { req }) => {
    const id = req.params.id;
    if (!validateId(id)) {
      throw new Error('Invalid user ID');
    }
    return true;
  }),
], (req, res, next) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Sample users for demonstration
    const sampleUsers = [
      { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
      { id: 2, name: 'Bob Smith', email: 'bob@example.com' },
      { id: 3, name: 'Carol Davis', email: 'carol@example.com' },
    ];

    const user = sampleUsers.find(u => u.id === userId);

    if (!user) {
      const error = new Error(`User with ID ${userId} not found`);
      error.statusCode = 404;
      return next(error);
    }

    res.json({
      data: user,
      meta: {
        timestamp: new Date().toISOString(),
      },
    });
  } catch (error) {
    next(error);
  }
});

// ==================== CATCH-ALL ROUTE ====================

// All other routes
app.all('*', notFoundHandler);

// ==================== ERROR HANDLING MIDDLEWARE ====================

app.use(errorHandler);

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Starting graceful shutdown...');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Starting graceful shutdown...');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// For testing purposes
module.exports = { app, server };

// Enhanced version of app.js with minimal security improvements
// Maintains original simplicity while adding critical security features

const express = require('express');
const app = express();
require('dotenv').config();

// ==================== SECURITY IMPROVEMENTS ====================

// 1. Basic rate limiting (simple implementation without external package)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // max requests per window

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { count: 1, startTime: now });
  } else {
    const userData = requestCounts.get(ip);

    if (now - userData.startTime > RATE_LIMIT_WINDOW) {
      // Reset counter after window expires
      userData.count = 1;
      userData.startTime = now;
    } else if (userData.count >= RATE_LIMIT_MAX) {
      return res.status(429).json({
        error: 'Too many requests. Please try again later.',
        timestamp: new Date().toISOString()
      });
    } else {
      userData.count++;
    }
  }

  next();
});

// 2. Input sanitization helper
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;

  // Basic sanitization - in production, use a library like DOMPurify
  return input
    .replace(/[<>]/g, '') // Remove HTML tags
    .replace(/javascript:/gi, '') // Remove javascript protocol
    .replace(/[\0\x08\x09\x1a\n\r"'\\\%]/g, char => {
      // Escape potentially dangerous characters for SQL
      const escapeMap = {
        '\0': '\\0',
        '\x08': '\\b',
        '\x09': '\\t',
        '\x1a': '\\z',
        '\n': '\\n',
        '\r': '\\r',
        '"': '\\"',
        "'": "\\'",
        '\\': '\\\\',
        '%': '\\%'
      };
      return escapeMap[char] || char;
    })
    .trim();
};

// 3. Error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error(`Error at ${req.method} ${req.path}:`, {
    message: err.message,
    timestamp: new Date().toISOString(),
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const message = statusCode === 500 ? 'Internal Server Error' : err.message;

  res.status(statusCode).json({
    error: message,
    timestamp: new Date().toISOString(),
    path: req.path
  });
};

// 4. Security headers
app.use((req, res, next) => {
  // Set basic security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Remove server fingerprinting
  res.removeHeader('X-Powered-By');

  next();
});

// ==================== ENHANCED ROUTES ====================

app.get('/health', (req, res, next) => {
  try {
    // Validate query parameter if provided
    const details = req.query.details;
    if (details && details !== 'true' && details !== 'false') {
      const error = new Error('Invalid details parameter. Must be "true" or "false"');
      error.statusCode = 400;
      throw error;
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (details === 'true') {
      response.details = {
        nodeVersion: process.version,
        platform: process.platform,
        memory: process.memoryUsage()
      };
    }

    res.json(response);
  } catch (error) {
    next(error);
  }
});

app.get('/users', (req, res, next) => {
  try {
    // Validate and sanitize query parameters
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
    const search = req.query.search ? sanitizeInput(req.query.search) : '';

    if (isNaN(limit) || limit < 1 || limit > 100) {
      const error = new Error('Invalid limit parameter. Must be between 1 and 100');
      error.statusCode = 400;
      throw error;
    }

    // Sample users with sanitized data
    const users = [
      { id: 1, name: 'Alice Johnson', email: 'alice@example.com' },
      { id: 2, name: 'Bob Smith', email: 'bob@example.com' }
    ];

    // Simple search functionality with sanitized input
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply limit
    const result = filteredUsers.slice(0, limit);

    res.json({
      data: result,
      meta: {
        total: filteredUsers.length,
        returned: result.length,
        limit: limit,
        search: search || null,
        timestamp: new Date().toISOString()
      }
    });
  } catch (error) {
    next(error);
  }
});

// New secure endpoint with POST method
app.post('/users', (req, res, next) => {
  try {
    // Note: For POST requests, you would typically parse JSON body
    // This is a simplified example - in real apps, use body-parser middleware

    res.status(501).json({
      error: 'POST method not implemented in this demo version',
      message: 'Use GET /users for retrieving user data',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res, next) => {
  const error = new Error(`Not Found: ${req.method} ${req.originalUrl}`);
  error.statusCode = 404;
  next(error);
});

// Global error handler (must be last middleware)
app.use(errorHandler);

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;

// Clean up rate limiter data periodically
setInterval(() => {
  const now = Date.now();
  for (const [ip, data] of requestCounts.entries()) {
    if (now - data.startTime > RATE_LIMIT_WINDOW) {
      requestCounts.delete(ip);
    }
  }
}, RATE_LIMIT_WINDOW);

app.listen(PORT, () => {
  console.log(`Enhanced secure server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = app;

