// Improved Express application with security best practices
// and comprehensive error handling

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ======================
// Security Middleware
// ======================

// Set security headers using Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
}));

// Enable CORS with safe defaults
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again after 15 minutes',
    standardHeaders: true,
    legacyHeaders: false,
});

app.use(limiter);

// Parse JSON with size limit to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging middleware
app.use(morgan('combined')); // Use 'dev' for development, 'combined' for production

// ======================
// Custom Middleware
// ======================

// Request validation error handler
const validateRequest = (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
        return res.status(400).json({
            success: false,
            errors: errors.array().map(err => ({
                param: err.param,
                msg: err.msg,
                value: err.value,
            })),
        });
    }
    next();
};

// Async error handling wrapper
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// ======================
// Routes with Validation
// ======================

/**
 * @route GET /health
 * @desc Health check endpoint
 * @access Public
 */
app.get('/health', (req, res) => {
    res.json({
        status: 'OK',
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memoryUsage: process.memoryUsage(),
    });
});

/**
 * @route GET /users
 * @desc Get users with pagination and filtering
 * @access Public
 */
app.get(
    '/users',
    [
        query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        query('name').optional().isString().trim().escape().withMessage('Name must be a string'),
        query('email').optional().isEmail().withMessage('Invalid email format'),
    ],
    validateRequest,
    asyncHandler(async (req, res) => {
        try {
            const { page = 1, limit = 10, name, email } = req.query;

            // Simulate database query with filtering
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
                { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
            ];

            // Apply filters
            let filteredUsers = users;
            if (name) {
                filteredUsers = filteredUsers.filter(user => 
                    user.name.toLowerCase().includes(name.toLowerCase())
                );
            }
            if (email) {
                filteredUsers = filteredUsers.filter(user => 
                    user.email.toLowerCase() === email.toLowerCase()
                );
            }

            // Calculate pagination
            const startIndex = (page - 1) * limit;
            const endIndex = page * limit;
            const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

            // Sanitize response - remove sensitive data
            const sanitizedUsers = paginatedUsers.map(user => ({
                id: user.id,
                name: user.name,
                role: user.role, // Consider if role should be exposed
            }));

            res.json({
                success: true,
                data: sanitizedUsers,
                pagination: {
                    page: parseInt(page),
                    limit: parseInt(limit),
                    total: filteredUsers.length,
                    pages: Math.ceil(filteredUsers.length / limit),
                },
            });
        } catch (error) {
            console.error('Error fetching users:', error);
            throw new Error('Failed to fetch users');
        }
    })
);

/**
 * @route POST /users
 * @desc Create a new user
 * @access Private (add authentication middleware in production)
 */
app.post(
    '/users',
    [
        body('name').notEmpty().trim().escape().withMessage('Name is required'),
        body('email').isEmail().normalizeEmail().withMessage('Valid email is required'),
        body('password')
            .isLength({ min: 8 })
            .withMessage('Password must be at least 8 characters')
            .matches(/^(?=.*\d)(?=.*[a-z])(?=.*[A-Z])(?=.*[!@#$%^&*])/)
            .withMessage('Password must contain at least one uppercase, one lowercase, one number and one special character'),
    ],
    validateRequest,
    asyncHandler(async (req, res) => {
        try {
            const { name, email, password } = req.body;

            // In production:
            // 1. Check if user already exists
            // 2. Hash password (never store plain text!)
            // 3. Save to database

            // Simulate user creation
            const newUser = {
                id: Date.now(),
                name,
                email,
                createdAt: new Date().toISOString(),
            };

            // Never return password or hashed password in response
            res.status(201).json({
                success: true,
                message: 'User created successfully',
                data: {
                    id: newUser.id,
                    name: newUser.name,
                    email: newUser.email,
                    createdAt: newUser.createdAt,
                },
            });
        } catch (error) {
            console.error('Error creating user:', error);
            throw new Error('Failed to create user');
        }
    })
);

/**
 * @route GET /users/:id
 * @desc Get user by ID
 * @access Public
 */
app.get(
    '/users/:id',
    [
        // Validate ID parameter
        param('id').isInt({ min: 1 }).withMessage('User ID must be a positive integer'),
    ],
    validateRequest,
    asyncHandler(async (req, res) => {
        try {
            const userId = parseInt(req.params.id);

            // Simulate database lookup
            const users = [
                { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
                { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
            ];

            const user = users.find(u => u.id === userId);

            if (!user) {
                return res.status(404).json({
                    success: false,
                    message: 'User not found',
                });
            }

            // Sanitize response
            const sanitizedUser = {
                id: user.id,
                name: user.name,
                // Excluding email for privacy in this example
            };

            res.json({
                success: true,
                data: sanitizedUser,
            });
        } catch (error) {
            console.error('Error fetching user:', error);
            throw new Error('Failed to fetch user');
        }
    })
);

// ======================
// Error Handling Middleware
// ======================

// 404 handler
app.use((req, res, next) => {
    res.status(404).json({
        success: false,
        message: 'Route not found',
        path: req.path,
        method: req.method,
    });
});

// Global error handler
app.use((err, req, res, next) => {
    console.error('Global error handler:', err);

    // Default to 500 if no status code
    const statusCode = err.statusCode || 500;

    // Don't expose stack traces in production
    const response = {
        success: false,
        message: err.message || 'Internal server error',
    };

    if (process.env.NODE_ENV === 'development') {
        response.stack = err.stack;
    }

    // Handle specific error types
    if (err.name === 'ValidationError') {
        return res.status(400).json({
            success: false,
            message: 'Validation error',
            errors: err.errors || err.details,
        });
    }

    if (err.name === 'UnauthorizedError') {
        return res.status(401).json({
            success: false,
            message: 'Unauthorized access',
        });
    }

    res.status(statusCode).json(response);
});

// ======================
// Server Configuration
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Shutting down gracefully...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Shutting down gracefully...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

module.exports = { app, server };

