// Minimal improved version focusing on core security practices
// while maintaining simplicity of original app.js

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

const app = express();

// ======================
// Essential Security Middleware
// ======================

// Security headers - CRITICAL for production
app.use(helmet());

// CORS with safe defaults
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : 'http://localhost:3000',
    methods: ['GET'],
}));

// Rate limiting - prevent basic DoS attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // 100 requests per IP
    message: 'Too many requests from this IP',
    standardHeaders: true,
});

app.use(limiter);

// Request size limits - prevent memory exhaustion attacks
app.use(express.json({ limit: '10kb' }));

// ======================
// Improved Routes with Error Handling
// ======================

/**
 * Health check endpoint
 * - Added error handling
 * - No sensitive information exposed
 */
app.get('/health', (req, res, next) => {
    try {
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString(),
            // Excluding process info unless needed for monitoring
        });
    } catch (error) {
        next(error);
    }
});

/**
 * Users endpoint with:
 * - Query parameter validation
 * - Response sanitization
 * - Error handling
 */
app.get('/users', (req, res, next) => {
    try {
        // Validate query parameters
        const { page, limit } = req.query;

        // Basic validation
        if (page && (!Number.isInteger(Number(page)) || Number(page) < 1)) {
            return res.status(400).json({
                error: 'Invalid page parameter. Must be a positive integer'
            });
        }

        if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
            return res.status(400).json({
                error: 'Invalid limit parameter. Must be between 1 and 100'
            });
        }

        // Simulate data fetch with error handling
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user', password: 'hashed_password_here' },
            { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin', password: 'hashed_password_here' },
        ];

        // Sanitize response - NEVER expose passwords or sensitive data
        const sanitizedUsers = users.map(user => ({
            id: user.id,
            name: user.name,
            // Email exposure decision: Only expose if business requires it
            // email: user.email,
        }));

        res.json(sanitizedUsers);

    } catch (error) {
        console.error('Error in /users endpoint:', error);
        next(error);
    }
});

// ======================
// Essential Error Handlers
// ======================

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not Found',
        path: req.path,
        method: req.method
    });
});

// Global error handler
app.use((err, req, res, next) => {
    console.error('Application error:', err);

    // Determine appropriate status code
    const statusCode = err.statusCode || 500;

    // Response based on environment
    const response = {
        error: 'Internal Server Error'
    };

    // Only show details in development
    if (process.env.NODE_ENV === 'development') {
        response.message = err.message;
        response.stack = err.stack;
    }

    res.status(statusCode).json(response);
});

// ======================
// Server Configuration
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
});

// Handle graceful shutdown
['SIGTERM', 'SIGINT'].forEach(signal => {
    process.on(signal, () => {
        console.log(`${signal} received. Shutting down gracefully...`);
        server.close(() => {
            console.log('Server closed');
            process.exit(0);
        });

        // Force shutdown after 10 seconds
        setTimeout(() => {
            console.error('Could not close connections in time, forcefully shutting down');
            process.exit(1);
        }, 10000);
    });
});

module.exports = { app, server };

