// Improved application with enhanced error handling and input validation
// Security best practices implemented

const express = require('express');
const helmet = require('helmet'); // Security headers
const cors = require('cors'); // CORS configuration
const rateLimit = require('express-rate-limit'); // Rate limiting
const { body, validationResult } = require('express-validator'); // Input validation

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration - explicitly set allowed origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : 'http://localhost:3000',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));

// Body parsing middleware with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use('/api/', limiter);

// ========== CUSTOM MIDDLEWARE ==========

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  next();
});

// Request sanitization middleware
app.use((req, res, next) => {
  // Basic sanitization - remove potential script tags
  const sanitize = (obj) => {
    if (typeof obj === 'string') {
      return obj.replace(/<script.*?>.*?<\/script>/gi, '');
    }
    if (Array.isArray(obj)) {
      return obj.map(sanitize);
    }
    if (obj && typeof obj === 'object') {
      return Object.fromEntries(
        Object.entries(obj).map(([key, value]) => [key, sanitize(value)])
      );
    }
    return obj;
  };

  if (req.body) req.body = sanitize(req.body);
  if (req.query) req.query = sanitize(req.query);
  next();
});

// ========== ENHANCED ROUTES WITH VALIDATION ==========

app.get('/health', (req, res) => {
  // Enhanced health check
  const healthStatus = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memoryUsage: process.memoryUsage(),
    pid: process.pid,
    nodeVersion: process.version
  };

  res.status(200).json(healthStatus);
});

// GET /users with query parameter validation
app.get('/users', 
  // Validation middleware
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
  ],
  (req, res) => {
  // Check validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      success: false, 
      errors: errors.array(),
      message: 'Validation failed' 
    });
  }

  try {
    // Sample data with additional robustness
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date().toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date().toISOString()
      },
    ];

    // Add pagination support
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const paginatedUsers = users.slice(startIndex, endIndex);

    res.status(200).json({
      success: true,
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: users.length,
        totalPages: Math.ceil(users.length / limit)
      }
    });

  } catch (error) {
    next(error); // Pass to error handler
  }
});

// POST /users with comprehensive validation
app.post('/users',
  [
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]*$/).withMessage('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),

    body('password')
      .optional()
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      .matches(/^(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).*$/).withMessage('Password must contain at least one uppercase letter, one lowercase letter, and one number')
  ],
  (req, res, next) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          success: false, 
          errors: errors.array() 
        });
      }

      // Process validated data
      const { name, email, age, password } = req.body;

      // Simulate user creation
      const newUser = {
        id: Date.now(), // Simple ID generation
        name: name.trim(),
        email: email.toLowerCase(),
        age: age || null,
        createdAt: new Date().toISOString()
      };

      // In real application, you would save to database

      res.status(201).json({
        success: true,
        message: 'User created successfully',
        data: newUser
      });

    } catch (error) {
      next(error);
    }
  }
);

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 Handler
app.use((req, res, next) => {
  res.status(404).json({
    success: false,
    message: 'Resource not found',
    path: req.url,
    method: req.method
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error(`[ERROR] ${new Date().toISOString()} - ${req.method} ${req.url}`);
  console.error(error.stack);

  // Determine error type and respond appropriately
  const statusCode = error.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : error.message;

  res.status(statusCode).json({
    success: false,
    message: message,
    ...(process.env.NODE_ENV === 'development' && { 
      stack: error.stack,
      details: error 
    })
  });
});

// ========== SERVER SETUP WITH GRACEFUL SHUTDOWN ==========

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Unhandled promise rejection handler
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Consider restarting the process in production
  if (process.env.NODE_ENV === 'production') {
    server.close(() => {
      process.exit(1);
    });
  }
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Consider restarting the process in production
  if (process.env.NODE_ENV === 'production') {
    server.close(() => {
      process.exit(1);
    });
  }
});

module.exports = app;

{
  "name": "secure-express-app",
  "version": "1.0.0",
  "description": "Express application with enhanced security and error handling",
  "main": "app_improved.js",
  "scripts": {
    "start": "node app_improved.js",
    "dev": "nodemon app_improved.js",
    "test": "jest --testTimeout=10000",
    "security-check": "npm audit"
  },
  "keywords": [
    "express",
    "security",
    "validation",
    "error-handling"
  ],
  "author": "Security Reviewer",
  "license": "MIT",
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^6.10.0",
    "express-validator": "^7.0.1"
  },
  "devDependencies": {
    "nodemon": "^3.0.1",
    "jest": "^29.6.2",
    "supertest": "^6.3.3"
  },
  "engines": {
    "node": ">=16.0.0"
  }
}

const request = require('supertest');
const app = require('../app_improved');

describe('Security Features Tests', () => {
  describe('CORS Configuration', () => {
    it('should include proper CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBe('http://localhost:3000');
    });

    it('should reject unauthorized origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'http://unauthorized.com');

      // Depending on CORS configuration
      expect(response.status).toBe(200); // Still 200 but headers may differ
    });
  });

  describe('Security Headers', () => {
    it('should include security headers via Helmet', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['x-powered-by']).toBeUndefined();
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBe('0');
    });
  });

  describe('Rate Limiting', () => {
    it('should apply rate limiting to API endpoints', async () => {
      const requests = [];
      for (let i = 0; i < 110; i++) {
        requests.push(request(app).get('/health'));
      }

      const responses = await Promise.all(requests);
      const rateLimitedResponses = responses.filter(r => r.status === 429);

      // Should have some rate limited responses after 100 requests
      expect(rateLimitedResponses.length).toBeGreaterThan(0);
    });
  });

  describe('Input Validation', () => {
    it('should reject invalid email format', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'Test User',
          email: 'invalid-email',
          age: 25
        });

      expect(response.status).toBe(400);
      expect(response.body.success).toBe(false);
      expect(response.body.errors[0].msg).toContain('email');
    });

    it('should reject SQL injection attempts', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: "'; DROP TABLE users; --",
          email: 'test@example.com'
        });

      expect(response.status).toBe(400);
      // Name validation should fail due to special characters
      expect(response.body.errors).toBeDefined();
    });

    it('should reject XSS attempts in body', async () => {
      const response = await request(app)
        .post('/users')
        .send({
          name: 'Test <script>alert("xss")</script>',
          email: 'test@example.com'
        });

      // Should be sanitized or rejected
      expect(response.status).toBe(400);
    });
  });

  describe('Error Handling', () => {
    it('should return 404 for non-existent routes', async () => {
