// Secure Express application with enhanced error handling and input validation
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();

// ======================
// 1. SECURITY MIDDLEWARE
// ======================

// Set security headers using Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"], // Consider removing unsafe-inline in production
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { 
    error: 'Too many requests from this IP, please try again later.' 
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ======================
// 2. LOGGING CONFIGURATION
// ======================

// Create logger instance
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    })
  ]
});

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    logger.info({
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    });
  });

  next();
});

// ======================
// 3. ROUTES WITH VALIDATION
// ======================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.status(200).json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to process health check'
    });
  }
});

// Users endpoint with query parameter validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
], (req, res) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg
        }))
      });
    }

    const { limit = 10, offset = 0 } = req.query;

    // Demo user data (in real app, this would come from a database)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: new Date('2023-01-15T10:30:00Z').toISOString()
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: new Date('2023-02-20T14:45:00Z').toISOString()
      },
    ];

    // Apply pagination (simplified example)
    const paginatedUsers = users.slice(parseInt(offset), parseInt(offset) + parseInt(limit));

    res.status(200).json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit: parseInt(limit),
        offset: parseInt(offset),
        hasMore: parseInt(offset) + parseInt(limit) < users.length
      }
    });
  } catch (error) {
    logger.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to retrieve user data'
    });
  }
});

// Example: User creation endpoint with comprehensive validation
app.post('/users', [
  // Comprehensive input validation
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Must be a valid email address')
    .normalizeEmail(),

  body('age')
    .optional()
    .isInt({ min: 13, max: 120 }).withMessage('Age must be between 13 and 120'),
], async (req, res) => {
  try {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg
        }))
      });
    }

    const { name, email, age } = req.body;

    // Sanitize and process data
    const sanitizedName = name.trim();
    const sanitizedEmail = email.toLowerCase().trim();

    // In a real app: Save to database
    // const newUser = await User.create({ name: sanitizedName, email: sanitizedEmail, age });

    logger.info(`New user created: ${sanitizedEmail}`);

    res.status(201).json({
      message: 'User created successfully',
      data: {
        id: Math.floor(Math.random() * 1000) + 100, // Mock ID
        name: sanitizedName,
        email: sanitizedEmail,
        age: age || null,
        createdAt: new Date().toISOString()
      }
    });
  } catch (error) {
    logger.error('Error creating user:', error);

    // Handle specific error types
    if (error.code === '23505') { // PostgreSQL duplicate key error
      return res.status(409).json({ 
        error: 'Conflict',
        message: 'User with this email already exists'
      });
    }

    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to create user'
    });
  }
});

// ======================
// 4. ERROR HANDLING MIDDLEWARE
// ======================

// 404 Not Found handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', error);

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  const errorResponse = {
    error: 'Internal Server Error',
    message: 'Something went wrong',
    timestamp: new Date().toISOString()
  };

  if (!isProduction && error.stack) {
    errorResponse.stack = error.stack;
  }

  res.status(error.status || 500).json(errorResponse);
});

// Handle uncaught promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // In production, you might want to gracefully shutdown
  if (process.env.NODE_ENV === 'production') {
    process.exit(1);
  }
});

// ======================
// 5. SERVER CONFIGURATION
// ======================

// Get port from environment variable or use default
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handler
const gracefulShutdown = () => {
  logger.info('Received shutdown signal, gracefully closing server...');

  // Close server
  server.close(() => {
    logger.info('Server closed');

    // Close database connections, cleanup resources here
    // if (db) db.close();

    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    logger.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Start server
const server = app.listen(PORT, HOST, () => {
  logger.info(`Server running on http://${HOST}:${PORT}`);
  logger.info('Environment:', process.env.NODE_ENV || 'development');
});

// Handle shutdown signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = { app, server };

