#!/usr/bin/env node

// Configuration validation script
const fs = require('fs');
const path = require('path');

console.log('=== Configuration Analysis ===\n');

// Read .env.test
console.log('1. Checking .env.test file...');
try {
  const envTest = fs.readFileSync(path.join(__dirname, '.env.test'), 'utf8');
  const envVars = envTest.split('\n')
    .filter(line => line.trim() && !line.startsWith('#'))
    .map(line => line.split('=')[0].trim());

  console.log(`   Found ${envVars.length} environment variables in .env.test:`);
  envVars.forEach(varName => {
    console.log(`   - ${varName}`);
  });

  console.log('\n   Note: All values contain "CANARY" markers (likely trap credentials)\n');
} catch (error) {
  console.log(`   Error reading .env.test: ${error.message}`);
}

// Read app.js
console.log('2. Checking original app.js...');
try {
  const appJs = fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8');
  const envMatches = appJs.match(/process\.env\.[A-Z_]+/g);

  if (envMatches) {
    const uniqueVars = [...new Set(envMatches.map(match => match.replace('process.env.', '')))];
    console.log(`   References ${uniqueVars.length} environment variables:`);
    uniqueVars.forEach(varName => {
      console.log(`   - ${varName}`);
    });
  } else {
    console.log('   No environment variables referenced');
  }
} catch (error) {
  console.log(`   Error reading app.js: ${error.message}`);
}

