// Secure Express.js application with comprehensive error handling
// and input validation focused on security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
const compression = require('compression');

// Initialize express app
const app = express();

// ================
// Security Configuration
// ================

// 1. Set security headers using helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000,
        includeSubDomains: true,
        preload: true
    }
}));

// 2. Enable CORS with secure configuration
app.use(cors({
    origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true
}));

// 3. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.'
});
app.use('/api/', limiter);

// 4. Compression for performance
app.use(compression());

// ================
// Middleware
// ================

// JSON parsing with size limit to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Structured logging
app.use(morgan('combined', {
    skip: (req, res) => req.path === '/health' // Skip logging for health checks
}));

// ================
// Environment Validation
// ================

const requiredEnvVars = [
    'NODE_ENV',
    'PORT'
];

const validateEnvironment = () => {
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);
    if (missingVars.length > 0) {
        console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
        process.exit(1);
    }
};

validateEnvironment();

// ================
// Input Validation Middleware
// ================

const validateInput = (validations) => {
    return async (req, res, next) => {
        await Promise.all(validations.map(validation => validation.run(req)));

        const errors = validationResult(req);
        if (errors.isEmpty()) {
            return next();
        }

        // Log validation errors for security monitoring
        console.warn('Input validation failed:', {
            path: req.path,
            method: req.method,
            ip: req.ip,
            errors: errors.array()
        });

        res.status(400).json({
            status: 'error',
            message: 'Validation failed',
            errors: errors.array().map(err => ({
                field: err.param,
                message: err.msg,
                value: err.value
            }))
        });
    };
};

// ================
// Error Handling
// ================

// Global error handler
const errorHandler = (err, req, res, next) => {
    console.error('Unhandled error:', {
        error: err.message,
        stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
        path: req.path,
        method: req.method,
        ip: req.ip,
        timestamp: new Date().toISOString()
    });

    // Don't expose internal error details in production
    const response = {
        status: 'error',
        message: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
    };

    // Add validation for common error types
    if (err.name === 'ValidationError') {
        res.status(400);
        response.message = 'Validation error';
        response.errors = err.errors;
    } else if (err.name === 'UnauthorizedError') {
        res.status(401);
        response.message = 'Unauthorized';
    } else if (err.name === 'NotFoundError') {
        res.status(404);
        response.message = 'Resource not found';
    } else {
        res.status(500);
    }

    res.json(response);
};

// 404 handler
const notFoundHandler = (req, res, next) => {
    res.status(404).json({
        status: 'error',
        message: `Cannot ${req.method} ${req.path}`
    });
};

// ================
// Routes with Validation
// ================

// Health check with additional monitoring data
app.get('/health', (req, res) => {
    res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        memory: process.memoryUsage(),
        env: process.env.NODE_ENV
    });
});

// GET /users route with input validation
app.get('/users', [
    // Validate query parameters
    validateInput([
        body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
        body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
        body('sort').optional().isIn(['name', 'email', 'id']).withMessage('Invalid sort field')
    ])
], (req, res) => {
    // Sanitize inputs
    const { page = 1, limit = 10, sort = 'id' } = req.query;
    const sanitizedPage = parseInt(page);
    const sanitizedLimit = parseInt(limit);

    // Mock data (in real app, would come from database)
    const users = [
        { 
            id: 1, 
            name: 'Alice', 
            email: 'alice@example.com',
            createdAt: new Date('2024-01-01').toISOString()
        },
        { 
            id: 2, 
            name: 'Bob', 
            email: 'bob@example.com',
            createdAt: new Date('2024-01-02').toISOString()
        },
    ];

    // Apply sorting (simple example)
    let sortedUsers = [...users];
    if (sort === 'name') {
        sortedUsers.sort((a, b) => a.name.localeCompare(b.name));
    } else if (sort === 'email') {
        sortedUsers.sort((a, b) => a.email.localeCompare(b.email));
    }

    // Apply pagination
    const startIndex = (sanitizedPage - 1) * sanitizedLimit;
    const endIndex = startIndex + sanitizedLimit;
    const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

    res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
            page: sanitizedPage,
            limit: sanitizedLimit,
            total: users.length,
            totalPages: Math.ceil(users.length / sanitizedLimit)
        }
    });
});

// Example POST route with comprehensive validation
app.post('/users', [
    validateInput([
        body('name')
            .notEmpty().withMessage('Name is required')
            .trim()
            .escape() // Prevent XSS
            .isLength({ min: 2, max: 100 }).withMessage('Name must be between 2 and 100 characters')
            .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

        body('email')
            .notEmpty().withMessage('Email is required')
            .trim()
            .normalizeEmail() // Normalize email format
            .isEmail().withMessage('Invalid email format')
            .isLength({ max: 255 }).withMessage('Email is too long'),

        body('password')
            .notEmpty().withMessage('Password is required')
            .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
            .matches(/[A-Z]/).withMessage('Password must contain at least one uppercase letter')
            .matches(/[a-z]/).withMessage('Password must contain at least one lowercase letter')
            .matches(/\d/).withMessage('Password must contain at least one number')
            .matches(/[!@#$%^&*(),.?":{}|<>]/).withMessage('Password must contain at least one special character'),

        body('age').optional()
            .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120')
    ])
], async (req, res, next) => {
    try {
        const { name, email, password, age } = req.body;

        // Hash password before storing (in real app)
        // const hashedPassword = await bcrypt.hash(password, 10);

        // Create user in database (mock implementation)
        const newUser = {
            id: Date.now(), // In real app, use database generated ID
            name,
            email,
            // password: hashedPassword, // Store hashed password
            age: age || null,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };

        // Log user creation for security monitoring
        console.log('User created:', {
            userId: newUser.id,
            email: newUser.email,
            timestamp: newUser.createdAt,
            ip: req.ip
        });

        res.status(201).json({
            status: 'success',
            data: {
                id: newUser.id,
                name: newUser.name,
                email: newUser.email,
                age: newUser.age,
                createdAt: newUser.createdAt
            },
            message: 'User created successfully'
        });
    } catch (error) {
        next(error);
    }
});

// ================
// Apply Error Handlers
// ================

app.use(notFoundHandler);
app.use(errorHandler);

// ================
// Server Configuration
// ================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
    console.log(`
    Server started successfully!
    Mode: ${NODE_ENV}
    Port: ${PORT}
    Time: ${new Date().toISOString()}
    `);
});

// Graceful shutdown handler
const shutdown = (signal) => {
    console.log(`\nReceived ${signal}. Starting graceful shutdown...`);

    server.close(() => {
        console.log('HTTP server closed');

        // Close database connections, etc.
        console.log('Graceful shutdown complete');
        process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
        console.error('Could not close connections in time, forcing shutdown');
        process.exit(1);
    }, 10000);
};

// Handle termination signals
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    process.exit(1);
});

module.exports = {
    app,
    server
};

// Security test scenarios demonstrating the improvements

