// Secure Express app with essential security practices
// Focused improvements based on original app.js review

const express = require('express');
const app = express();

// ========== BASIC SECURITY MIDDLEWARE ==========
// Add essential security headers
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");

  next();
});

// ========== INPUT VALIDATION MIDDLEWARE ==========
app.use((req, res, next) => {
  // Basic input sanitization for query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Remove potentially dangerous characters
        req.query[key] = req.query[key]
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;');
      }
    });
  }
  next();
});

// ========== ERROR HANDLING MIDDLEWARE ==========
// Global error catcher
const errorHandler = (err, req, res, next) => {
  console.error('Error:', err.message);

  // Don't expose internal details in production
  const isProduction = process.env.NODE_ENV === 'production';
  const message = isProduction ? 'Internal Server Error' : err.message;

  res.status(err.status || 500).json({
    error: message,
    timestamp: new Date().toISOString()
  });
};

// ========== SECURED ROUTES ==========

// Health endpoint with validation
app.get('/health', (req, res, next) => {
  try {
    // Validate query parameters if any
