          req.query.name.replace(/[<>]/g, '') : undefined
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com' 
      },
    ];

    res.json({
      success: true,
      data: users,
      pagination: {
        page,
        limit,
        total: users.length,
